    @Override public boolean dispatchTouchEvent(android.view.MotionEvent event){int action=event.getActionMasked();if(action==MotionEvent.ACTION_DOWN){edgeDownX=event.getX();edgeDownY=event.getY();if(undoSnackbar!=null&&!touchInside(event,undoSnackbar))dismissUndoSnackbar();}else if(action==MotionEvent.ACTION_UP){float dx=event.getX()-edgeDownX,dy=event.getY()-edgeDownY;if(Math.abs(dx)>dp(80)&&Math.abs(dx)>Math.abs(dy)*1.3f){if(sideDrawerOverlay!=null){closeDrawer();return true;}if(screen==6){stepWalk(dx<0?1:-1);return true;}if(screen==7){stepWalkReader(dx<0?1:-1);return true;}if(screen==2&&dx<0){handleBack();return true;}if(screen==0&&dx<0){showDrawer();return true;}if(edgeDownX<=dp(24)&&dx>0){handleBack();return true;}}}return super.dispatchTouchEvent(event);}
    boolean touchInside(MotionEvent event,View view){int[] xy=new int[2];view.getLocationOnScreen(xy);float x=event.getRawX(),y=event.getRawY();return x>=xy[0]&&x<=xy[0]+view.getWidth()&&y>=xy[1]&&y<=xy[1]+view.getHeight();}
