    class Notebook {
        String id=UUID.randomUUID().toString(),name;int color;
        Notebook(String name){this.name=name;color=notebookColors[new Random().nextInt(notebookColors.length)];}
        Notebook(JSONObject o){id=o.optString("id",id);name=o.optString("name","未命名记本");color=o.optInt("color",notebookColors[0]);}
        JSONObject json()throws Exception{JSONObject o=new JSONObject();o.put("id",id);o.put("name",name);o.put("color",color);return o;}
    }
    Notebook findNotebook(String id){for(Notebook b:notebooks)if(b.id.equals(id))return b;return null;}
    String notebookName(String id){Notebook b=findNotebook(id);return id==null?"全部记本":b==null?"无记本":b.name;}
    boolean inNotebook(Note n,String id){return id==null||id.equals(n.notebookId);}
    int notebookCount(String id){int count=0;for(Note n:notes)if(inNotebook(n,id))count++;return count;}
    void chooseNotebook(String current,java.util.function.Consumer<String> action,boolean all){
        ArrayList<String> names=new ArrayList<>(),ids=new ArrayList<>();
        if(all){names.add((current==null?"✓ ":"")+"全部记本");ids.add(null);}
        names.add(("".equals(current)?"✓ ":"")+"无记本");ids.add("");
        for(Notebook b:notebooks){names.add((b.id.equals(current)?"✓ ":"")+b.name);ids.add(b.id);}
        styledOptions("选择记本",null,names,i->action.accept(ids.get(i)),"取消",null);
    }
    void assignNotebook(Note target){flushPendingBlockPersist();chooseNotebook(target.notebookId,id->{target.notebookId=id;persist();toast("已更改记本："+notebookName(id));if(screen==11)buildNotebookNotes();},false);}
    void nameNotebook(Notebook existing){
        EditText input=dialogInput("记本名称",existing==null?"":existing.name,1);
        input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(40)});
        styledPanel(existing==null?"新建记本":"重命名记本","为你的日记取一个名字",input,"取消",null,"保存",()->{
            String value=input.getText().toString().trim();if(value.isEmpty()){toast("名称不能为空");nameNotebook(existing);return;}
            for(Notebook b:notebooks)if(b!=existing&&b.name.equals(value)){toast("已存在同名记本");nameNotebook(existing);return;}
            if(existing==null)notebooks.add(new Notebook(value));else existing.name=value;persist();buildNotebooks();
        });
    }
    void deleteNotebooks(Set<String> ids){
        if(ids.isEmpty()){toast("请先选择记本");return;}Set<String> deleting=new HashSet<>(ids);
        styledConfirm("删除 "+deleting.size()+" 个记本？","笔记会保留，更改为“无记本”。","取消",null,"删除",()->{
            notebooks.removeIf(b->deleting.contains(b.id));for(Note n:notes)if(deleting.contains(n.notebookId))n.notebookId="";for(Note n:trash)if(deleting.contains(n.notebookId))n.notebookId="";
            if(deleting.contains(activeNotebookId))activeNotebookId=null;if(deleting.contains(walkNotebookId))walkNotebookId=null;
            notebookSelection=false;selectedNotebooks.clear();persist();buildNotebooks();
        });
    }
    void notebookMenu(View anchor,Notebook b){
        PopupMenu menu=new PopupMenu(this,anchor);for(String label:new String[]{"改变颜色","重命名","删除"})menu.getMenu().add(label);
        menu.setOnMenuItemClickListener(item->{String label=item.getTitle().toString();if(label.equals("重命名"))nameNotebook(b);else if(label.equals("删除"))deleteNotebooks(Collections.singleton(b.id));else{
            styledOptions("记本颜色",null,Arrays.asList("鼠尾草绿","陶土粉","雾蓝","麦穗黄","浅紫","青绿"),i->{b.color=notebookColors[i];persist();buildNotebooks();},"取消",null);
        }return true;});menu.show();
    }
    void buildNotebooks(){
        finishEditorSession();closeDrawer();screen=10;root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg);setContentView(root);
        LinearLayout header=row();header.setPadding(dp(16),dp(8),dp(18),dp(8));root.addView(header,new LinearLayout.LayoutParams(-1,dp(58)));header.addView(iconButton("菜单",this::showDrawer),new LinearLayout.LayoutParams(dp(42),dp(42)));
        header.addView(text(notebookSelection?"已选 "+selectedNotebooks.size()+" 个记本":"记本",20,ink,true),new LinearLayout.LayoutParams(0,-1,1));
        TextView select=button(notebookSelection?"完成":"选择",()->{notebookSelection=!notebookSelection;selectedNotebooks.clear();buildNotebooks();});header.addView(select,new LinearLayout.LayoutParams(dp(56),dp(40)));
        FrameLayout area=new FrameLayout(this);root.addView(area,new LinearLayout.LayoutParams(-1,0,1));ScrollView scroll=new ScrollView(this);area.addView(scroll,new FrameLayout.LayoutParams(-1,-1));
        LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);list.setPadding(dp(14),dp(12),dp(14),dp(100));scroll.addView(list);
        if(notebooks.isEmpty())emptyHome(list,"还没有记本","点右下角加号，创建你的第一本日记本");
        LinearLayout shelf=null;
        for(int i=0;i<notebooks.size();i++){
            Notebook b=notebooks.get(i);if(i%2==0){shelf=row();shelf.setGravity(Gravity.TOP);list.addView(shelf,new LinearLayout.LayoutParams(-1,-2));}
            FrameLayout cover=new FrameLayout(this);GradientDrawable coverBg=shape(b.color,9);coverBg.setStroke(dp(selectedNotebooks.contains(b.id)?3:1),selectedNotebooks.contains(b.id)?ink:withAlpha(ink,25));cover.setBackground(coverBg);cover.setElevation(dp(3));
            LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,dp(218),1);cp.setMargins(dp(8),dp(8),dp(8),dp(16));shelf.addView(cover,cp);
            View spine=new View(this);spine.setBackgroundColor(withAlpha(Color.BLACK,22));FrameLayout.LayoutParams sp=new FrameLayout.LayoutParams(dp(7),-1);sp.leftMargin=dp(9);cover.addView(spine,sp);
            LinearLayout label=new LinearLayout(this);label.setOrientation(LinearLayout.VERTICAL);label.setPadding(dp(28),dp(28),dp(18),0);TextView title=text((selectedNotebooks.contains(b.id)?"✓ ":"")+b.name,19,Color.WHITE,true);title.setMaxLines(3);title.setEllipsize(TextUtils.TruncateAt.END);label.addView(title,new LinearLayout.LayoutParams(-1,-2));TextView count=text(notebookCount(b.id)+" 篇日记",12,withAlpha(Color.WHITE,210),false);label.addView(count,new LinearLayout.LayoutParams(-1,dp(34)));cover.addView(label,new FrameLayout.LayoutParams(-1,-2));
            FrameLayout more=iconButton("moreHorizontal",()->{});more.setContentDescription(b.name+"的记本操作");FrameLayout.LayoutParams mp=new FrameLayout.LayoutParams(dp(48),dp(44),Gravity.RIGHT|Gravity.BOTTOM);more.setOnClickListener(v->notebookMenu(more,b));cover.addView(more,mp);more.setVisibility(notebookSelection?View.GONE:View.VISIBLE);
            cover.setOnClickListener(v->{if(notebookSelection){if(!selectedNotebooks.add(b.id))selectedNotebooks.remove(b.id);buildNotebooks();}else{activeNotebookId=b.id;buildNotebookNotes();}});
            cover.setOnLongClickListener(v->{notebookSelection=true;selectedNotebooks.add(b.id);buildNotebooks();return true;});
        }
        if(notebooks.size()%2==1)shelf.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));
        if(notebookSelection){TextView delete=button("删除所选记本",()->deleteNotebooks(selectedNotebooks));root.addView(delete,new LinearLayout.LayoutParams(-1,dp(54)));}
        else{FrameLayout fab=new FrameLayout(this);fab.setContentDescription("添加记本");fab.setBackground(shape(ink,40));fab.setElevation(dp(5));fab.addView(new IconGlyph("plus",Color.WHITE),new FrameLayout.LayoutParams(dp(26),dp(26),Gravity.CENTER));fab.setOnClickListener(v->nameNotebook(null));FrameLayout.LayoutParams fp=new FrameLayout.LayoutParams(dp(56),dp(56),Gravity.RIGHT|Gravity.BOTTOM);fp.setMargins(0,0,dp(18),dp(18));area.addView(fab,fp);}bottomNav(2);
    }
    void buildNotebookNotes(){
        finishEditorSession();closeDrawer();screen=11;selectionMode=false;root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg);setContentView(root);
        LinearLayout header=row();header.setPadding(dp(16),dp(8),dp(18),dp(8));root.addView(header,new LinearLayout.LayoutParams(-1,dp(58)));header.addView(iconButton("返回",this::buildNotebooks),new LinearLayout.LayoutParams(dp(42),dp(42)));TextView title=text(notebookName(activeNotebookId),19,ink,true);title.setSingleLine();title.setEllipsize(TextUtils.TruncateAt.END);header.addView(title,new LinearLayout.LayoutParams(0,-1,1));header.addView(iconButton("菜单",this::showDrawer),new LinearLayout.LayoutParams(dp(42),dp(42)));
        FrameLayout area=new FrameLayout(this);root.addView(area,new LinearLayout.LayoutParams(-1,0,1));ScrollView scroll=new ScrollView(this);area.addView(scroll);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);list.setPadding(dp(18),dp(12),dp(18),dp(96));scroll.addView(list);
        ArrayList<Note> entries=new ArrayList<>();for(Note n:notes)if(inNotebook(n,activeNotebookId))entries.add(n);entries.sort((a,b)->a.pinned==b.pinned?Long.compare(b.updatedAt,a.updatedAt):(a.pinned?-1:1));for(Note n:entries)addPreviewCard(list,n,"");if(entries.isEmpty())emptyHome(list,"记本还是空的","点加号写下第一篇日记");
        FrameLayout fab=new FrameLayout(this);fab.setContentDescription("添加记本");fab.setBackground(shape(ink,40));fab.addView(new IconGlyph("plus",Color.WHITE),new FrameLayout.LayoutParams(dp(26),dp(26),Gravity.CENTER));fab.setOnClickListener(v->createNote());FrameLayout.LayoutParams fp=new FrameLayout.LayoutParams(dp(56),dp(56),Gravity.RIGHT|Gravity.BOTTOM);fp.setMargins(0,0,dp(18),dp(18));area.addView(fab,fp);bottomNav(2);
    }
    void bottomNav(int selected){LinearLayout nav=row();nav.setGravity(Gravity.CENTER);nav.setBackgroundColor(Color.WHITE);nav.setPadding(dp(8),dp(4),dp(8),dp(6));root.addView(nav,new LinearLayout.LayoutParams(-1,dp(62)));nav.setElevation(dp(4));String[] names={"首页","漫步","记本","我的"};String[] icons={"home","clock","book","user"};for(int position=0;position<4;position++){final int page=position;LinearLayout item=new LinearLayout(this);item.setOrientation(LinearLayout.VERTICAL);item.setGravity(Gravity.CENTER);View icon=page==3?new UserGlyph(selected==3?ink:muted):new IconGlyph(icons[page],selected==page?ink:muted);item.addView(icon,new LinearLayout.LayoutParams(dp(23),dp(23)));TextView label=text(names[page],11,selected==page?ink:muted,selected==page);label.setGravity(Gravity.CENTER);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(20));lp.topMargin=dp(2);item.addView(label,lp);item.setOnClickListener(v->{if(page==0){screen=0;buildHome();}else if(page==1)buildWalk();else if(page==2)buildNotebooks();else buildMy();});nav.addView(item,new LinearLayout.LayoutParams(0,-1,1));}}
    String noteContent(Note n){String content=n.text==null?"":n.text;if(!n.blocks.isEmpty()){String blocks=n.blocksText();if(!blocks.isEmpty())content=content.isEmpty()?blocks:content+"\n"+blocks;}return content;}
    String markdownPlainText(String source){return parseMarkdown(source==null?"":source).rendered.toString();}
    SpannableStringBuilder markdownStyledText(String source){MarkdownResult parsed=parseMarkdown(source==null?"":source);for(MarkdownStyleRange style:parsed.styles)applyMarkdownStyle(parsed.rendered,style.renderStart,style.renderEnd,style.marker);return parsed.rendered;}
    boolean contains(String source,String query){return source!=null&&source.toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT));}
    boolean noteMatchesQuery(Note n,String query){if(query==null||query.isEmpty()||contains(n.title+"\n"+noteContent(n),query))return true;for(String tag:n.tags)if(contains(tag,query))return true;return false;}
    String preview(Note n){String value=markdownPlainText(noteContent(n)).replace('\n',' ').trim();if(value.isEmpty())return "还没有正文";return value.length()>110?value.substring(0,110)+"…":value;}
    String searchPreview(Note n,String query){String value=markdownPlainText(noteContent(n)).replace('\n',' ').trim();if(query==null||query.isEmpty()||value.isEmpty())return preview(n);int found=value.toLowerCase(Locale.ROOT).indexOf(query.toLowerCase(Locale.ROOT));if(found<0)return preview(n);int start=Math.max(0,found-38),end=Math.min(value.length(),found+query.length()+62);return (start>0?"…":"")+value.substring(start,end)+(end<value.length()?"…":"");}
    SpannableString highlight(String source,String query){SpannableString out=new SpannableString(source);if(query==null||query.isEmpty())return out;String lower=source.toLowerCase(Locale.ROOT),term=query.toLowerCase(Locale.ROOT);int at=0;while((at=lower.indexOf(term,at))>=0){out.setSpan(new BackgroundColorSpan(0xFFFFE48A),at,at+term.length(),0);out.setSpan(new ForegroundColorSpan(ink),at,at+term.length(),0);at+=term.length();}return out;}
    SpannableString highlightGray(String source,String query){SpannableString out=new SpannableString(source);if(query==null||query.isEmpty())return out;String lower=source.toLowerCase(Locale.ROOT),term=query.toLowerCase(Locale.ROOT);int at=0;while((at=lower.indexOf(term,at))>=0){out.setSpan(new BackgroundColorSpan(0xFFD9DDE1),at,at+term.length(),0);out.setSpan(new ForegroundColorSpan(ink),at,at+term.length(),0);at+=term.length();}return out;}
