    String dateLabel(long millis){Calendar c=Calendar.getInstance();c.setTimeInMillis(millis);return String.format(Locale.CHINA,"%d月%d日 %02d:%02d:%02d",c.get(Calendar.MONTH)+1,c.get(Calendar.DAY_OF_MONTH),c.get(Calendar.HOUR_OF_DAY),c.get(Calendar.MINUTE),c.get(Calendar.SECOND));}
    String timestampLabel(long millis){Calendar c=Calendar.getInstance();c.setTimeInMillis(millis);return String.format(Locale.CHINA,"%d年%d月%d日 %02d:%02d:%02d",c.get(Calendar.YEAR),c.get(Calendar.MONTH)+1,c.get(Calendar.DAY_OF_MONTH),c.get(Calendar.HOUR_OF_DAY),c.get(Calendar.MINUTE),c.get(Calendar.SECOND));}
