    void handleWidgetIntent(Intent intent){if(intent==null)return;String action=intent.getAction();if(ACTION_WIDGET_NEW.equals(action)){setIntent(new Intent(this,MainActivity.class));createNote();}else if(ACTION_WIDGET_OPEN.equals(action)){String id=intent.getStringExtra(EXTRA_WIDGET_NOTE_ID);for(Note item:notes)if(item.id.equals(id)){setIntent(new Intent(this,MainActivity.class));openNote(item,"");return;}setIntent(new Intent(this,MainActivity.class));buildHome();toast("这篇笔记已不存在");}}
    void openNote(Note target,String query){finishEditorSession();blockSelectionMode=false;selectedBlocks.clear();previewMode=false;editorReturnScreen=screen==7||screen==6?6:screen;if(screen==6||screen==7)walkReturnNote=target;current=notes.indexOf(target);if(current<0)current=0;note=target;pendingSearch=query==null?"":query;boolean blockHit=false;for(Block b:target.blocks)if(contains(b.text,pendingSearch)){blockHit=true;break;}isLinear=target.blocks.isEmpty()||(!pendingSearch.isEmpty()&&contains(target.text,pendingSearch)&&!blockHit);buildEditor();}
