    void updateSearchResults(String query){if(searchResults==null)return;searchResults.removeAllViews();ScrollView scroll=new ScrollView(this);searchResults.addView(scroll);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);list.setPadding(dp(18),dp(8),dp(18),dp(24));scroll.addView(list);if(!activeTagFilter.isEmpty()){TextView summary=text(folderSummary(activeTagFilter),13,muted,false);summary.setPadding(dp(2),0,dp(2),dp(8));list.addView(summary,new LinearLayout.LayoutParams(-1,-2));}String term=query==null?"":query;boolean any=false;HashSet<String> labelsInMatchingNotes=new HashSet<>();ArrayList<Note> matchingNotes=new ArrayList<>();ArrayList<Note> ordered=searchOrder();if(!term.isEmpty()||!activeTagFilter.isEmpty())for(Note n:ordered){boolean matches=term.isEmpty()?noteHasLabelInScope(n,activeTagFilter):noteMatchesQuery(n,term);if(matches){matchingNotes.add(n);labelsInMatchingNotes.addAll(n.tags);}}ArrayList<String> matchingLabels=new ArrayList<>();for(String label:labels){if(isLabelInScope(label,activeTagFilter)&&(term.isEmpty()||contains(label,term)||labelsInMatchingNotes.contains(label)||hasMatchingDescendant(labelsInMatchingNotes,label)))matchingLabels.add(label);if(term.isEmpty()&&activeTagFilter.isEmpty()&&matchingLabels.size()>=40)break;}if(!matchingLabels.isEmpty()){LinearLayout heading=row();FolderGlyph icon=new FolderGlyph();heading.addView(icon,new LinearLayout.LayoutParams(dp(20),dp(20)));LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(-1,dp(36));list.addView(heading,hp);for(String label:matchingLabels){TextView tag=text(label+"    ›",14,ink,false);if(!term.isEmpty())tag.setText(highlight(label+"    ›",term));tag.setPadding(dp(12),0,dp(12),0);tag.setBackground(shape(Color.WHITE,14));LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(-1,dp(46));tp.bottomMargin=dp(8);list.addView(tag,tp);tag.setOnClickListener(v->{activeTagFilter=label;updateSearchResults(query);});}any=true;}if(term.isEmpty()&&activeTagFilter.isEmpty()){if(!any)emptyHome(list,"无","输入关键词搜索笔记，或选择一个标签目录。");return;}TextView notesHead=text("笔记",16,ink,true);LinearLayout.LayoutParams nh=new LinearLayout.LayoutParams(-1,dp(42));nh.topMargin=dp(4);list.addView(notesHead,nh);int count=0;for(Note n:matchingNotes){if(noteHasLabelInScope(n,activeTagFilter)){addPreviewCard(list,n,term);count++;}}if(count==0&&!any)emptyHome(list,"无","没有找到相关笔记。");}
