    void showMembership(){LinearLayout content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);String[] rows={"免费用户：笔记、搜索、标签、漫步、回收站与 JSON 备份，本地离线使用","PRO：近七天和按月漫步筛选","PRO：批量整理、Markdown / PDF 等高级导出","PRO：多种主题、字体、隐私保护与全部桌面小组件","更多功能还在路上"};for(int i=0;i<rows.length;i++){TextView line=text(rows[i],14,i==0?muted:ink,i>0&&i<4);line.setGravity(Gravity.TOP);line.setPadding(0,dp(5),0,dp(5));content.addView(line,new LinearLayout.LayoutParams(-1,-2));}TextView status=text(memberEntitlementStatus,13,muted,false);status.setPadding(0,dp(8),0,dp(4));content.addView(status,new LinearLayout.LayoutParams(-1,-2));String subtitle=memberAccessToken.isEmpty()?(memberEmail.isEmpty()?"未登录 · 登录仅用于会员权益，不会上传本机笔记":"已验证邮箱："+memberEmail+" · 登录仅用于会员权益") :"已验证邮箱："+memberEmail+" · 笔记仅保存在本机";Runnable primary=memberAccessToken.isEmpty()?this::showEmailLogin:()->refreshMemberStatus(true);String primaryLabel=memberAccessToken.isEmpty()?"邮箱验证码登录":"刷新会员状态";Runnable secondary=memberAccessToken.isEmpty()?null:this::showRedeemMembership;String secondaryLabel=memberAccessToken.isEmpty()?"稍后再说":"兑换会员";if(!memberAccessToken.isEmpty()){TextView logout=text("退出会员账号",13,muted,false);logout.setGravity(Gravity.CENTER);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(38));lp.topMargin=dp(5);content.addView(logout,lp);logout.setOnClickListener(v->styledConfirm("退出会员账号","只清除本机登录状态，不会删除本机笔记。","取消",null,"退出",this::logoutMember));}styledPanel("会员与普通用户",subtitle,content,secondaryLabel,secondary,primaryLabel,primary);if(!memberAccessToken.isEmpty()&&memberEntitlementStatus.equals("尚未查询会员权益"))refreshMemberStatus(false);}
    String memberEmail="",memberAccessToken="";
    void showEmailLogin(){EditText email=dialogInput("邮箱地址",null,1);email.setSingleLine(true);email.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);styledPanel("邮箱验证", "按需登录会员账号；免费本地功能无需登录。",email,"返回",null,"发送验证码",()->{String address=email.getText().toString().trim();if(!android.util.Patterns.EMAIL_ADDRESS.matcher(address).matches()){toast("请输入有效邮箱");return;}requestMemberCode(address);});}
    void requestMemberCode(String email){String base=BuildConfig.MEMBER_API_BASE_URL;if(base.trim().isEmpty()){toast("会员邮箱服务尚未连接，当前仍可离线使用本地功能");return;}JSONObject payload=new JSONObject();try{payload.put("email",email);}catch(Exception ignored){}memberRequest("/v1/auth/email/send-code",payload,(success,response)->{if(!success){toast("验证码发送失败，请稍后重试");return;}EditText code=dialogInput("邮箱验证码",null,1);code.setSingleLine(true);code.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);styledPanel("输入验证码","验证码已发送至 "+email,code,"取消",null,"验证并登录",()->verifyMemberCode(email,code.getText().toString().trim()));});}
    interface ApiResult{void done(boolean success,JSONObject response);}
    void memberRequest(String path,JSONObject payload,ApiResult result){memberHttpRequest("POST",path,payload,false,result);}
    void memberAuthorizedRequest(String method,String path,JSONObject payload,ApiResult result){memberHttpRequest(method,path,payload,true,result);}
    void memberHttpRequest(String method,String path,JSONObject payload,boolean authorized,ApiResult result){securityExecutor.execute(()->{HttpURLConnection connection=null;boolean success=false;JSONObject response=new JSONObject();try{URL url=new URL(BuildConfig.MEMBER_API_BASE_URL.replaceAll("/+$","")+path);connection=(HttpURLConnection)url.openConnection();connection.setRequestMethod(method);connection.setConnectTimeout(8000);connection.setReadTimeout(8000);connection.setRequestProperty("Accept","application/json");if(authorized)connection.setRequestProperty("Authorization","Bearer "+memberAccessToken);if(payload!=null){connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/json; charset=utf-8");try(OutputStream out=connection.getOutputStream()){out.write(payload.toString().getBytes(StandardCharsets.UTF_8));}}int status=connection.getResponseCode();InputStream stream=status>=200&&status<300?connection.getInputStream():connection.getErrorStream();if(stream!=null){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[2048];int length;while((length=stream.read(buffer))!=-1)bytes.write(buffer,0,length);String body=new String(bytes.toByteArray(),StandardCharsets.UTF_8);if(!body.trim().isEmpty())response=new JSONObject(body);}success=status>=200&&status<300;}catch(Exception ignored){}finally{if(connection!=null)connection.disconnect();}boolean ok=success;JSONObject data=response;runOnUiThread(()->{if(!isFinishing())result.done(ok,data);});});}
    void refreshMemberStatus(boolean showFeedback){if(memberAccessToken.isEmpty()){proMemberActive=false;memberEntitlementStatus="登录后可查询会员权益";showMembership();return;}if(BuildConfig.MEMBER_API_BASE_URL.trim().isEmpty()){proMemberActive=false;memberEntitlementStatus="会员服务尚未连接；本地功能可继续使用";showMembership();return;}memberEntitlementStatus="正在查询会员权益…";showMembership();memberAuthorizedRequest("GET","/v1/me",null,(accountOk,account)->{if(!accountOk){proMemberActive=false;memberEntitlementStatus="账号状态暂不可用，请检查网络后重试";showMembership();if(showFeedback)toast("会员服务暂不可用，本地功能不受影响");return;}memberAuthorizedRequest("GET","/v1/entitlements",null,(ok,data)->{if(!ok){proMemberActive=false;memberEntitlementStatus="权益查询失败，请稍后重试";if(showFeedback)toast("权益查询失败，本地功能不受影响");}else{JSONObject entitlement=data.optJSONObject("entitlement");if(entitlement==null)entitlement=data;String state=entitlement.optString("status","");proMemberActive=entitlement.optBoolean("active",false)||"active".equalsIgnoreCase(state)||"valid".equalsIgnoreCase(state);memberEntitlementStatus=proMemberActive?"PRO 会员有效"+(entitlement.optString("valid_until","").isEmpty()?"":" · 有效期至 "+entitlement.optString("valid_until")):"当前账号暂无有效 PRO 会员";if(showFeedback)toast(proMemberActive?"会员权益已更新":"当前账号暂无有效会员");}showMembership();});});}
    void showRedeemMembership(){if(memberAccessToken.isEmpty()){toast("请先验证邮箱登录");showEmailLogin();return;}EditText code=dialogInput("输入管理员发放的兑换码",null,1);code.setSingleLine(true);styledPanel("兑换会员","转账到账并核实后，管理员会向你提供兑换码。兑换权益绑定当前邮箱。",code,"取消",null,"兑换",()->{String value=code.getText().toString().trim();if(value.isEmpty()){toast("请输入兑换码");return;}if(BuildConfig.MEMBER_API_BASE_URL.trim().isEmpty()){toast("会员兑换服务尚未连接，请稍后再试");return;}JSONObject payload=new JSONObject();try{payload.put("code",value);}catch(Exception ignored){}memberEntitlementStatus="正在验证兑换码…";memberAuthorizedRequest("POST","/v1/membership/redeem",payload,(ok,data)->{if(!ok){JSONObject error=data.optJSONObject("error");memberEntitlementStatus=error==null?"兑换服务暂不可用":"兑换未成功："+error.optString("message","请检查兑换码");toast(memberEntitlementStatus);showMembership();return;}memberEntitlementStatus="兑换已处理，正在刷新会员权益…";toast(data.optString("message","兑换成功，正在刷新权益"));refreshMemberStatus(false);});});}
    void logoutMember(){memberAccessToken="";memberEmail="";proMemberActive=false;memberEntitlementStatus="尚未查询会员权益";getSharedPreferences("suiyi",0).edit().remove("memberTokenEncrypted").remove("recoveryEmail").apply();showMembership();}
    void verifyMemberCode(String email,String code){if(code.isEmpty()){toast("请输入验证码");return;}JSONObject payload=new JSONObject();try{payload.put("email",email);payload.put("code",code);}catch(Exception ignored){}memberRequest("/v1/auth/email/verify-code",payload,(success,response)->{String token=response.optString("access_token",response.optString("accessToken",""));if(!success||token.isEmpty()){toast("验证失败或会员服务尚未连接");return;}try{String encryptedToken=encryptStore(token);memberEmail=email;memberAccessToken=token;getSharedPreferences("suiyi",0).edit().putString("recoveryEmail",email).putString("memberTokenEncrypted",encryptedToken).apply();memberEntitlementStatus="邮箱验证完成，正在读取会员状态…";toast("邮箱验证完成，本机笔记仍只保存在本地");refreshMemberStatus(false);}catch(Exception e){toast("登录凭据安全保存失败");}});}

    boolean hasAppLock(){SharedPreferences p=getSharedPreferences("suiyi",0);return !p.getString("lockSalt","").isEmpty()&&!p.getString("lockHash","").isEmpty();}
    EditText pinInput(String hint){EditText input=dialogInput(hint,null,1);input.setSingleLine(true);input.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_VARIATION_PASSWORD);return input;}
    void showPrivacySettings(){styledPanel("隐私保护","笔记与标签已使用本机安全密钥加密",null,lockingEnabled?"关闭应用锁":null,lockingEnabled?this::confirmDisablePin:null,lockingEnabled?"更改 PIN":"设置 PIN",this::setupPin);}
    void setupPin(){EditText first=pinInput("设置 4 至 12 位数字 PIN");styledPanel("设置应用锁",null,first,"取消",null,"继续",()->{String value=first.getText().toString();if(!value.matches("[0-9]{4,12}")){toast("PIN 需为 4 至 12 位数字");return;}EditText second=pinInput("再次输入 PIN");styledPanel("确认应用锁 PIN",null,second,"取消",null,"启用",()->{if(!value.equals(second.getText().toString())){toast("两次输入不一致");return;}try{byte[] salt=new byte[16],recoverySalt=new byte[16];SecureRandom random=new SecureRandom();random.nextBytes(salt);random.nextBytes(recoverySalt);String recovery=String.format(Locale.US,"%08d",random.nextInt(100000000));String encodedSalt=android.util.Base64.encodeToString(salt,android.util.Base64.NO_WRAP);String encodedRecoverySalt=android.util.Base64.encodeToString(recoverySalt,android.util.Base64.NO_WRAP);String hash=hashPin(value,salt),recoveryHash=hashPin(recovery,recoverySalt);getSharedPreferences("suiyi",0).edit().putString("lockSalt",encodedSalt).putString("lockHash",hash).putString("recoverySalt",encodedRecoverySalt).putString("recoveryHash",recoveryHash).putInt("pinFailures",0).putLong("pinLockUntil",0).apply();lockingEnabled=true;RecentNotesWidgetProvider.refresh(this);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);buildMy();showRecoveryCode(recovery);}catch(Exception e){toast("设置失败，请重试");}});});}
    void showRecoveryCode(String recovery){TextView instructions=text("请将恢复码保存在安全的地方。忘记 PIN 时可用它在本机重设。",14,muted,false);instructions.setGravity(Gravity.TOP);TextView code=text(recovery,24,ink,true);code.setGravity(Gravity.CENTER);code.setBackground(shape(0xFFF4F4F4,12));LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.addView(instructions,new LinearLayout.LayoutParams(-1,dp(58)));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,dp(58));cp.topMargin=dp(8);box.addView(code,cp);styledPanel("保存恢复码",null,box,null,null,"已保存",()->toast("应用锁已开启"));}
    void recoverPin(){EditText recovery=pinInput("输入 8 位本机恢复码");String email=getSharedPreferences("suiyi",0).getString("recoveryEmail","");String subtitle=email.isEmpty()?"使用设置应用锁时生成的本机恢复码重设 PIN；会员邮箱恢复可在主动验证邮箱后使用。":"使用本机恢复码，或通过已验证邮箱 "+email+" 找回。";styledPanel("忘记 PIN",subtitle,recovery,email.isEmpty()?null:"邮箱找回",email.isEmpty()?null:this::requestPinRecoveryCode,"验证恢复码",()->{if(!verifyRecoveryCode(recovery.getText().toString().trim())){toast("恢复码不正确");return;}setupPin();});}
    void requestPinRecoveryCode(){String email=getSharedPreferences("suiyi",0).getString("recoveryEmail","");if(email.isEmpty()){toast("尚未绑定恢复邮箱，请使用本机恢复码");return;}String base=BuildConfig.MEMBER_API_BASE_URL;if(base.trim().isEmpty()){toast("邮箱服务尚未连接，请使用本机恢复码");return;}JSONObject payload=new JSONObject();try{payload.put("email",email);}catch(Exception ignored){}memberRequest("/v1/auth/email/send-code",payload,(success,response)->{if(!success){toast("验证码发送失败，请使用本机恢复码");return;}EditText code=dialogInput("邮箱验证码",null,1);code.setSingleLine(true);code.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);styledPanel("邮箱找回 PIN","验证码已发送至 "+email,code,"取消",null,"验证",()->{JSONObject verify=new JSONObject();try{verify.put("email",email);verify.put("code",code.getText().toString().trim());}catch(Exception ignored){}memberRequest("/v1/auth/email/verify-code",verify,(verified,response2)->{if(!verified){toast("邮箱验证失败");return;}String token=response2.optString("access_token",response2.optString("accessToken",""));if(token.isEmpty()){toast("邮箱验证响应无效");return;}try{memberAccessToken=token;getSharedPreferences("suiyi",0).edit().putString("memberTokenEncrypted",encryptStore(token)).apply();setupPin();}catch(Exception e){toast("凭据保存失败，请使用本机恢复码");}});});});}
    boolean verifyRecoveryCode(String value){try{SharedPreferences p=getSharedPreferences("suiyi",0);String encodedSalt=p.getString("recoverySalt","");String encodedHash=p.getString("recoveryHash","");if(encodedSalt.isEmpty()||encodedHash.isEmpty())return false;byte[] salt=android.util.Base64.decode(encodedSalt,android.util.Base64.NO_WRAP);byte[] expected=android.util.Base64.decode(encodedHash,android.util.Base64.NO_WRAP);byte[] actual=android.util.Base64.decode(hashPin(value,salt),android.util.Base64.NO_WRAP);return MessageDigest.isEqual(expected,actual);}catch(Exception e){return false;}}
    String hashPin(String pin,byte[] salt)throws Exception{KeySpec spec=new PBEKeySpec(pin.toCharArray(),salt,120000,256);byte[] value=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA1").generateSecret(spec).getEncoded();return android.util.Base64.encodeToString(value,android.util.Base64.NO_WRAP);}
    boolean verifyPin(String value){try{SharedPreferences p=getSharedPreferences("suiyi",0);byte[] salt=android.util.Base64.decode(p.getString("lockSalt",""),android.util.Base64.NO_WRAP);byte[] expected=android.util.Base64.decode(p.getString("lockHash",""),android.util.Base64.NO_WRAP);byte[] actual=android.util.Base64.decode(hashPin(value,salt),android.util.Base64.NO_WRAP);return MessageDigest.isEqual(expected,actual);}catch(Exception e){return false;}}
    void confirmDisablePin(){EditText input=pinInput("输入当前 PIN 以关闭应用锁");styledPanel("关闭应用锁",null,input,"取消",null,"关闭",()->{if(!verifyPin(input.getText().toString())){toast("PIN 不正确");return;}getSharedPreferences("suiyi",0).edit().remove("lockSalt").remove("lockHash").remove("pinFailures").remove("pinLockUntil").apply();lockingEnabled=false;locked=false;RecentNotesWidgetProvider.refresh(this);getWindow().clearFlags(WindowManager.LayoutParams.FLAG_SECURE);buildMy();toast("应用锁已关闭");});}
    void showLockScreen(){locked=true;LinearLayout page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setGravity(Gravity.CENTER);page.setPadding(dp(32),dp(28),dp(32),dp(28));page.setBackgroundColor(bg);TextView title=text("碎忆已锁定",22,ink,true);title.setGravity(Gravity.CENTER);page.addView(title,new LinearLayout.LayoutParams(-1,dp(52)));TextView subtitle=text("输入 PIN 继续",14,muted,false);subtitle.setGravity(Gravity.CENTER);page.addView(subtitle,new LinearLayout.LayoutParams(-1,dp(38)));EditText input=pinInput("PIN");input.setGravity(Gravity.CENTER);LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(-1,dp(52));ip.topMargin=dp(16);page.addView(input,ip);TextView unlock=text("解锁",15,Color.WHITE,true);unlock.setGravity(Gravity.CENTER);unlock.setBackground(shape(ink,12));LinearLayout.LayoutParams up=new LinearLayout.LayoutParams(-1,dp(50));up.topMargin=dp(14);page.addView(unlock,up);unlock.setOnClickListener(v->{SharedPreferences p=getSharedPreferences("suiyi",0);long until=p.getLong("pinLockUntil",0);if(System.currentTimeMillis()<until){toast("请稍后再试");return;}unlock.setEnabled(false);unlock.setText("正在验证…");String candidate=input.getText().toString();securityExecutor.execute(()->{boolean valid=verifyPin(candidate);runOnUiThread(()->{if(isFinishing())return;unlock.setEnabled(true);unlock.setText("解锁");if(valid){p.edit().putInt("pinFailures",0).putLong("pinLockUntil",0).apply();locked=false;getWindow().clearFlags(WindowManager.LayoutParams.FLAG_SECURE);if(root!=null&&screen==0)buildHome();else refreshVisibleScreen();RecentNotesWidgetProvider.refresh(this);handleWidgetIntent(getIntent());}else{int failures=p.getInt("pinFailures",0)+1;SharedPreferences.Editor edit=p.edit().putInt("pinFailures",failures);if(failures>=5)edit.putInt("pinFailures",0).putLong("pinLockUntil",System.currentTimeMillis()+30000);edit.apply();input.setText("");toast(failures>=5?"尝试次数过多，请 30 秒后再试":"PIN 不正确");}});});});TextView forgot=text("忘记 PIN？使用恢复码",14,muted,false);forgot.setGravity(Gravity.CENTER);LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,dp(48));fp.topMargin=dp(8);page.addView(forgot,fp);forgot.setOnClickListener(v->recoverPin());setContentView(page);input.requestFocus();}
    void showStorageError(){getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);LinearLayout page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setGravity(Gravity.CENTER);page.setPadding(dp(28),dp(24),dp(28),dp(24));page.setBackgroundColor(bg);TextView title=text("无法解锁本地数据",20,ink,true);title.setGravity(Gravity.CENTER);page.addView(title,new LinearLayout.LayoutParams(-1,dp(54)));TextView detail=text("加密数据或本机安全密钥不可用。为保护笔记，应用没有重建空数据。请保留应用数据；如有 JSON 备份，可在恢复应用密钥后重新导入。",14,muted,false);detail.setGravity(Gravity.CENTER);page.addView(detail,new LinearLayout.LayoutParams(-1,dp(130)));setContentView(page);}

    ArrayList<Note> pendingExportNotes=new ArrayList<>();
    void showBulkActions(){if(!proMemberActive){showMembership();return;}String[] actions={"添加标签","移除标签","收藏 / 取消收藏","置顶 / 取消置顶","导出 Markdown / PDF","移入回收站"};styledOptions("批量整理","已选择 "+selectedNotes.size()+" 篇笔记",Arrays.asList(actions),index->{ArrayList<Note> chosen=new ArrayList<>(selectedNotes);switch(index){case 0:chooseBulkTag(chosen,true);break;case 1:chooseBulkTag(chosen,false);break;case 2:boolean favorite=false;for(Note item:chosen)if(!item.favorite){favorite=true;break;}for(Note item:chosen)item.favorite=favorite;saveBulk("已更新收藏状态");break;case 3:boolean pinned=false;for(Note item:chosen)if(!item.pinned){pinned=true;break;}for(Note item:chosen)item.pinned=pinned;saveBulk("已更新置顶状态");break;case 4:chooseAdvancedExport(chosen);break;case 5:moveBulkToTrash(chosen);break;}},"取消选择",()->{selectionMode=false;selectedNotes.clear();buildHome();});}
    void saveBulk(String message){persist();selectionMode=false;selectedNotes.clear();buildHome();toast(message);}
    void chooseBulkTag(ArrayList<Note> chosen,boolean add){if(add&&labels.isEmpty()){toast("请先创建标签");return;}if(labels.isEmpty()){toast("没有可移除的标签");return;}styledOptions(add?"添加标签":"移除标签","应用于 "+chosen.size()+" 篇笔记",labels,index->{String label=labels.get(index);for(Note item:chosen){if(add){if(!item.tags.contains(label))item.tags.add(label);}else item.tags.remove(label);}saveBulk(add?"已添加标签":"已移除标签");},"新建标签",add?()->{EditText input=dialogInput("标签名称",null,1);styledPanel("新建并添加标签",null,input,"取消",null,"添加",()->{String label=input.getText().toString().trim();if(label.isEmpty())return;if(!labels.contains(label))labels.add(label);for(Note item:chosen)if(!item.tags.contains(label))item.tags.add(label);saveBulk("已添加标签");});}:null);}
    void moveBulkToTrash(ArrayList<Note> chosen){HashMap<Note,Integer> positions=new HashMap<>();for(Note item:chosen)positions.put(item,notes.indexOf(item));ArrayList<Note> moved=new ArrayList<>(chosen);moved.sort((a,b)->Integer.compare(positions.get(b),positions.get(a)));for(Note item:moved){notes.remove(item);trash.add(0,item);}persist();selectionMode=false;selectedNotes.clear();buildHome();showUndoSnackbar("已移入回收站 "+moved.size()+" 篇",()->{moved.sort((a,b)->Integer.compare(positions.get(a),positions.get(b)));for(Note item:moved){trash.remove(item);notes.add(Math.max(0,Math.min(positions.get(item),notes.size())),item);}persist();buildHome();});}
    void chooseAdvancedExport(ArrayList<Note> source){if(source.isEmpty()){toast("没有可导出的笔记");return;}pendingExportNotes=new ArrayList<>(source);styledOptions("导出笔记","共 "+source.size()+" 篇，选择格式与保存位置",Arrays.asList("Markdown（.md）","PDF（.pdf）"),index->startAdvancedExport(index==0),null,null);}
    void startAdvancedExport(boolean markdown){Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType(markdown?"text/markdown":"application/pdf");intent.putExtra(Intent.EXTRA_TITLE,markdown?"碎忆笔记.md":"碎忆笔记.pdf");startActivityForResult(intent,markdown?REQUEST_MARKDOWN:REQUEST_PDF);}
    String markdownExport(List<Note> source){StringBuilder out=new StringBuilder();for(Note item:source){if(out.length()>0)out.append("\n\n---\n\n");out.append("# ").append(item.title.trim().isEmpty()?"无标题":item.title.trim()).append("\n\n");out.append("时间：").append(timestampLabel(item.updatedAt)).append("\n\n");if(!item.tags.isEmpty()){out.append("标签：");for(int i=0;i<item.tags.size();i++){if(i>0)out.append("、");out.append(item.tags.get(i));}out.append("\n\n");}out.append(noteContent(item).trim());}return out.toString();}
    void writeTextExport(android.net.Uri uri,boolean markdown){try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("无法写入文件");out.write(markdownExport(pendingExportNotes).getBytes(StandardCharsets.UTF_8));out.flush();toast("Markdown 已导出");}catch(Exception e){toast("导出失败，请重试");}}
    void writePdfExport(android.net.Uri uri){PdfDocument pdf=new PdfDocument();Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);paint.setColor(Color.BLACK);paint.setTextSize(12);int pageNumber=1;PdfDocument.Page page=null;Canvas canvas=null;float y=0,left=42,right=553,bottom=800;try{for(Note item:pendingExportNotes){ArrayList<String> paragraphs=new ArrayList<>();paragraphs.add(item.title.trim().isEmpty()?"无标题":item.title.trim());paragraphs.add("时间："+timestampLabel(item.updatedAt));if(!item.tags.isEmpty()){StringBuilder tags=new StringBuilder("标签：");for(int i=0;i<item.tags.size();i++){if(i>0)tags.append("、");tags.append(item.tags.get(i));}paragraphs.add(tags.toString());}paragraphs.addAll(Arrays.asList(noteContent(item).split("\\n",-1)));for(int paragraphIndex=0;paragraphIndex<paragraphs.size();paragraphIndex++){String paragraph=paragraphs.get(paragraphIndex);if(page==null||y>bottom-24){if(page!=null)pdf.finishPage(page);page=pdf.startPage(new PdfDocument.PageInfo.Builder(595,842,pageNumber++).create());canvas=page.getCanvas();y=48;}paint.setTypeface(paragraphIndex==0?Typeface.create(Typeface.DEFAULT,Typeface.BOLD):Typeface.DEFAULT);String remaining=paragraph.isEmpty()?" ":paragraph;do{int count=paint.breakText(remaining,true,right-left,null);if(count<=0)count=remaining.length();if(y>bottom){pdf.finishPage(page);page=pdf.startPage(new PdfDocument.PageInfo.Builder(595,842,pageNumber++).create());canvas=page.getCanvas();y=48;}canvas.drawText(remaining.substring(0,count),left,y,paint);remaining=remaining.substring(count);y+=18;}while(!remaining.isEmpty());y+=8;}}if(page!=null)pdf.finishPage(page);try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("无法写入文件");pdf.writeTo(out);}toast("PDF 已导出");}catch(Exception e){toast("PDF 导出失败，请重试");}finally{pdf.close();}}
