    void exportBackup(){Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("application/json");intent.putExtra(Intent.EXTRA_TITLE,"碎忆笔记备份.json");startActivityForResult(intent,REQUEST_EXPORT);}
    JSONObject backupJson()throws Exception{JSONObject root=new JSONObject();root.put("format","suiyi-notes");root.put("version",2);JSONArray books=new JSONArray();for(Notebook book:notebooks)books.put(book.json());root.put("notebooks",books);JSONArray n=new JSONArray();for(Note item:notes)n.put(item.json());root.put("notes",n);JSONArray t=new JSONArray();for(Note item:trash)t.put(item.json());root.put("trash",t);root.put("labels",new JSONArray(labels));root.put("pinnedLabels",new JSONArray(pinnedLabels));JSONArray time=new JSONArray();for(TimeEntry item:timeline)time.put(item.json());root.put("timeline",time);return root;}
    void writeBackup(android.net.Uri uri){try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("无法写入文件");out.write(backupJson().toString(2).getBytes(StandardCharsets.UTF_8));out.flush();toast("笔记已导出");}catch(Exception e){toast("导出失败，请重试");}}
    void importBackup(){styledOptions("导入笔记","选择要导入的文件类型",Arrays.asList("导入碎忆备份（JSON）","导入 Flomo 笔记（ZIP）"),index->{Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);if(index==0){intent.setType("application/json");startActivityForResult(intent,REQUEST_IMPORT);}else{intent.setType("application/zip");intent.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/zip","application/x-zip-compressed","application/octet-stream"});startActivityForResult(intent,REQUEST_FLOMO);}},"取消",null);}
    void readBackup(android.net.Uri uri){try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("无法读取文件");ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int length;while((length=in.read(buffer))!=-1)bytes.write(buffer,0,length);JSONObject data=new JSONObject(new String(bytes.toByteArray(),StandardCharsets.UTF_8));if(!"suiyi-notes".equals(data.optString("format")))throw new JSONException("不支持的备份格式");JSONArray incoming=data.optJSONArray("notes");if(incoming==null)throw new JSONException("备份中没有笔记");ArrayList<Note> imported=new ArrayList<>();for(int i=0;i<incoming.length();i++)imported.add(new Note(incoming.getJSONObject(i)));JSONArray incomingTrash=data.optJSONArray("trash");ArrayList<Note> importedTrash=new ArrayList<>();if(incomingTrash!=null)for(int i=0;i<incomingTrash.length();i++)importedTrash.add(new Note(incomingTrash.getJSONObject(i)));JSONArray incomingLabels=data.optJSONArray("labels");if(incomingLabels!=null)for(int i=0;i<incomingLabels.length();i++){String label=incomingLabels.getString(i);if(!labels.contains(label))labels.add(label);}JSONArray incomingPins=data.optJSONArray("pinnedLabels");if(incomingPins!=null)for(int i=0;i<incomingPins.length();i++){String label=incomingPins.getString(i);if(labels.contains(label)&&!pinnedLabels.contains(label))pinnedLabels.add(label);}JSONArray incomingBooks=data.optJSONArray("notebooks");HashMap<String,String> bookIds=new HashMap<>();ArrayList<Notebook> importedBooks=new ArrayList<>();if(incomingBooks!=null)for(int i=0;i<incomingBooks.length();i++){Notebook b=new Notebook(incomingBooks.getJSONObject(i));String oldId=b.id;b.id=UUID.randomUUID().toString();bookIds.put(oldId,b.id);importedBooks.add(b);}for(Note n:imported)n.notebookId=bookIds.getOrDefault(n.notebookId,"");for(Note n:importedTrash)n.notebookId=bookIds.getOrDefault(n.notebookId,"");notebooks.addAll(importedBooks);notes.addAll(0,imported);trash.addAll(0,importedTrash);JSONArray incomingTime=data.optJSONArray("timeline");if(incomingTime!=null)for(int i=0;i<incomingTime.length();i++)timeline.add(new TimeEntry(incomingTime.getJSONObject(i)));persist();buildMy();toast("已导入"+imported.size()+"篇笔记");}catch(Exception e){toast("导入失败：文件格式无效");}}
    void readFlomoZip(android.net.Uri uri){ArrayList<Note> imported=new ArrayList<>();int skipped=0,htmlFiles=0,entries=0;long totalBytes=0;try(InputStream raw=getContentResolver().openInputStream(uri);ZipInputStream zip=raw==null?null:new ZipInputStream(new BufferedInputStream(raw))){if(zip==null)throw new IOException("无法读取文件");ZipEntry entry;while((entry=zip.getNextEntry())!=null){if(++entries>20000)throw new IOException("ZIP 条目过多");if(entry.isDirectory()||!entry.getName().toLowerCase(Locale.ROOT).matches(".*\\.(html|htm)$")){zip.closeEntry();continue;}htmlFiles++;ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int count;while((count=zip.read(buffer))!=-1){totalBytes+=count;if(totalBytes>50L*1024*1024||bytes.size()+count>10*1024*1024)throw new IOException("ZIP 内容过大");bytes.write(buffer,0,count);}String html=new String(bytes.toByteArray(),StandardCharsets.UTF_8);ArrayList<FlomoEntry> parsed=parseFlomoHtml(html);for(FlomoEntry item:parsed){Note importedNote=new Note();importedNote.id=UUID.randomUUID().toString();importedNote.text=item.text;importedNote.updatedAt=item.createdAt;for(String path:item.tagPaths)if(!importedNote.tags.contains(path))importedNote.tags.add(path);imported.add(importedNote);}skipped+=countInvalidFlomoMemos(html,parsed.size());zip.closeEntry();}if(htmlFiles==0)throw new IOException("ZIP 中没有 HTML 笔记");if(imported.isEmpty())throw new IOException("没有可导入的笔记条目");imported.sort((a,b)->Long.compare(b.updatedAt,a.updatedAt));for(Note item:imported)for(String path:item.tags)ensureLabelPath(path);notes.addAll(0,imported);persist();buildHome();toast("Flomo 导入完成：新增 "+imported.size()+" 篇，跳过 "+skipped+" 篇");}catch(Exception e){toast("Flomo 导入失败，请确认选择的是有效 ZIP 文件");}}
    static class FlomoEntry{String text;long createdAt;LinkedHashSet<String>tagPaths=new LinkedHashSet<>();FlomoEntry(String value,long time){text=value;createdAt=time;}}
    ArrayList<FlomoEntry> parseFlomoHtml(String html){ArrayList<FlomoEntry> result=new ArrayList<>();try{String clean=html.replaceAll("(?is)<(script|style|head)\\b[^>]*>.*?</\\1>"," ");Pattern memoPattern=Pattern.compile("(?is)<div\\b[^>]*class\\s*=\\s*[\"'][^\"']*\\bmemo\\b[^\"']*[\"'][^>]*>");Matcher memoMatcher=memoPattern.matcher(clean);ArrayList<Integer> starts=new ArrayList<>();while(memoMatcher.find())starts.add(memoMatcher.start());if(starts.isEmpty()){FlomoEntry single=parseFlomoMemo(clean);if(single!=null)result.add(single);return result;}for(int i=0;i<starts.size();i++){int end=i+1<starts.size()?starts.get(i+1):clean.length();FlomoEntry item=parseFlomoMemo(clean.substring(starts.get(i),end));if(item!=null)result.add(item);}return result;}catch(Exception e){return result;}}
    FlomoEntry parseFlomoMemo(String html){try{String timeHtml=htmlClassContent(html,"time"),contentHtml=htmlClassContent(html,"content");if(timeHtml==null||contentHtml==null)return null;String time=htmlToPlainText(timeHtml).trim();Matcher date=Pattern.compile("(?<!\\d)(\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2})(?!\\d)").matcher(time);if(!date.find())return null;java.text.SimpleDateFormat format=new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.ROOT);format.setLenient(false);Date parsedDate=format.parse(date.group(1));if(parsedDate==null)return null;String plain=htmlToPlainText(contentHtml).replaceAll("\\n{3,}","\\n\\n").trim();if(plain.isEmpty())return null;FlomoEntry result=new FlomoEntry(plain,parsedDate.getTime());parseFlomoTags(plain,result.tagPaths);return result;}catch(Exception e){return null;}}
    String htmlClassContent(String html,String className){Pattern pattern=Pattern.compile("(?is)<([a-z][a-z0-9]*)\\b(?=[^>]*\\bclass\\s*=\\s*[\"'][^\"']*\\b"+Pattern.quote(className)+"\\b[^\"']*[\"'])[^>]*>(.*?)</\\1\\s*>");Matcher matcher=pattern.matcher(html);return matcher.find()?matcher.group(2):null;}
    String htmlToPlainText(String html){String safe=html.replaceAll("(?is)<(script|style)\\b[^>]*>.*?</\\1>"," ").replaceAll("(?i)<br\\s*/?>","\n").replaceAll("(?i)</(p|div|li|h[1-6]|ul|ol|blockquote)>","\n");return android.text.Html.fromHtml(safe,android.os.Build.VERSION.SDK_INT>=24?android.text.Html.FROM_HTML_MODE_LEGACY:0).toString().replace('\u00a0',' ').replace('\r','\n').replaceAll("[\\t ]+\\n","\n").replaceAll("\\n[\\t ]+","\n").trim();}
    int countInvalidFlomoMemos(String html,int valid){Matcher matcher=Pattern.compile("(?is)<div\\b[^>]*class\\s*=\\s*[\"'][^\"']*\\bmemo\\b[^\"']*[\"'][^>]*>").matcher(html);int total=0;while(matcher.find())total++;return Math.max(0,total-valid);}
    void parseFlomoTags(String text,Set<String> paths){String[] lines=text.split("\\n");ArrayList<String> headingPath=new ArrayList<>();Pattern heading=Pattern.compile("^\\s*(#{1,6})\\s+(.+?)\\s*#*\\s*$");Pattern tag=Pattern.compile("(?<![\\p{L}\\p{N}_])#([^\\s#]+(?:/[^\\s#]+)*)");for(String line:lines){Matcher h=heading.matcher(line);if(h.matches()){int level=h.group(1).length();String value=h.group(2).trim();while(headingPath.size()>=level)headingPath.remove(headingPath.size()-1);headingPath.add(value);StringBuilder path=new StringBuilder();for(String part:headingPath){if(path.length()>0)path.append('/');path.append(part);}if(path.length()>0)paths.add(path.toString());continue;}Matcher tags=tag.matcher(line);while(tags.find()){String value=tags.group(1).trim().replaceAll("^/+|/+$","").replaceAll("/{2,}","/");if(!value.isEmpty())paths.add(value);}}}
    void addTagPathAndParents(Set<String> paths,String path){StringBuilder prefix=new StringBuilder();for(String part:path.split("/")){String clean=part.trim();if(clean.isEmpty())continue;if(prefix.length()>0)prefix.append('/');prefix.append(clean);paths.add(prefix.toString());}}
    void ensureLabelPath(String path){StringBuilder prefix=new StringBuilder();for(String part:path.split("/")){String clean=part.trim();if(clean.isEmpty())continue;if(prefix.length()>0)prefix.append('/');prefix.append(clean);String value=prefix.toString();if(!labels.contains(value)){labels.add(value);collapsedLabelFolders.add(value);}}}
