    class FormatGlyph extends View{final String kind;final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);FormatGlyph(String value){super(MainActivity.this);kind=value;}@Override protected void onDraw(Canvas canvas){float scale=Math.min(getWidth(),getHeight())/24f;canvas.save();canvas.translate((getWidth()-24*scale)/2f,(getHeight()-24*scale)/2f);canvas.scale(scale,scale);p.setColor(ink);if(kind.equals("formatBold")){p.setTypeface(Typeface.create(Typeface.DEFAULT,Typeface.BOLD));p.setTextSize(18);canvas.drawText("B",6,18,p);}else if(kind.equals("formatUnderline")){p.setTypeface(Typeface.create(Typeface.DEFAULT,Typeface.NORMAL));p.setTextSize(17);canvas.drawText("U",5,17,p);p.setStrokeWidth(2);canvas.drawLine(5,21,19,21,p);}else{p.setStrokeWidth(4);p.setStrokeCap(Paint.Cap.ROUND);canvas.drawLine(7,17,17,7,p);p.setStrokeWidth(3);canvas.drawLine(9,19,18,10,p);canvas.drawLine(5,20,9,20,p);canvas.drawLine(17,6,19,4,p);}canvas.restore();}}
