        LinearLayout bar=row();bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(8),dp(4),dp(8),dp(4));bar.setBackgroundColor(Color.WHITE);bar.setElevation(dp(4));root.addView(bar,new LinearLayout.LayoutParams(-1,dp(52)));
        String[] kinds={"formatBold","formatUnderline","formatHighlight"};String[] descriptions={"加粗","下划线","荧光标记"};String[] markers={"**","<u>","=="};String[] closing={"**","</u>","=="};
