    void stepWalkReader(int delta){int currentIndex=walkNotes.indexOf(walkReturnNote);if(currentIndex<0)currentIndex=walkIndex;int next=Math.max(0,Math.min(walkNotes.size()-1,currentIndex+delta));if(next==currentIndex)return;walkIndex=(next/walkBatchSize)*walkBatchSize;buildWalkReader(walkNotes.get(next));}
    void refreshWalkNotes(){walkNotes.clear();Calendar today=Calendar.getInstance();today.set(Calendar.HOUR_OF_DAY,0);today.set(Calendar.MINUTE,0);today.set(Calendar.SECOND,0);today.set(Calendar.MILLISECOND,0);long todayStart=today.getTimeInMillis();int todayMonth=today.get(Calendar.MONTH),todayDay=today.get(Calendar.DAY_OF_MONTH),todayWeekday=today.get(Calendar.DAY_OF_WEEK);for(Note item:notes){Calendar c=Calendar.getInstance();c.setTimeInMillis(item.updatedAt);boolean match=true;if(walkFilter==1)match=item.updatedAt>=System.currentTimeMillis()-7L*24*60*60*1000;if(walkFilter==2)match=c.get(Calendar.YEAR)==walkMonth.get(Calendar.YEAR)&&c.get(Calendar.MONTH)==walkMonth.get(Calendar.MONTH);else if(walkFilter==3)match=item.updatedAt<todayStart&&c.get(Calendar.MONTH)==todayMonth&&c.get(Calendar.DAY_OF_MONTH)==todayDay;else if(walkFilter==4)match=item.updatedAt<todayStart&&c.get(Calendar.DAY_OF_MONTH)==todayDay;else if(walkFilter==5)match=item.updatedAt<todayStart&&c.get(Calendar.DAY_OF_WEEK)==todayWeekday;if(match&&inNotebook(item,walkNotebookId))walkNotes.add(item);}Collections.shuffle(walkNotes);walkIndex=0;if(walkReturnNote!=null){int returnedIndex=walkNotes.indexOf(walkReturnNote);if(returnedIndex>=0)walkIndex=(returnedIndex/walkBatchSize)*walkBatchSize;walkReturnNote=null;}walkLoaded=true;}
    String walkFilterLabel(){return walkTimeFilterLabel()+(walkNotebookId==null?"":" · "+notebookName(walkNotebookId));}
    String walkTimeFilterLabel(){if(walkFilter==1)return "近七天";if(walkFilter==2)return String.format(Locale.CHINA,"%d年%d月",walkMonth.get(Calendar.YEAR),walkMonth.get(Calendar.MONTH)+1);if(walkFilter==3)return "那年今日";if(walkFilter==4)return "那月今日";if(walkFilter==5)return "那周今日";return "全部笔记";}
    void stepWalk(int delta){if(walkNotes.isEmpty()||walkAnimating)return;int next=Math.max(0,Math.min(Math.max(0,walkNotes.size()-1),walkIndex+delta*walkBatchSize));if(next==walkIndex)return;if(walkCard==null){walkIndex=next;buildWalk();return;}walkAnimating=true;final int direction=delta>0?-1:1;View outgoing=walkCard;outgoing.animate().translationX(direction*getResources().getDisplayMetrics().widthPixels*.22f).alpha(.45f).setDuration(150).withEndAction(()->{walkIndex=next;buildWalk();if(walkCard!=null){walkCard.setTranslationX(-direction*getResources().getDisplayMetrics().widthPixels*.22f);walkCard.setAlpha(.45f);walkCard.animate().translationX(0).alpha(1f).setDuration(190).withEndAction(()->walkAnimating=false).start();}else walkAnimating=false;}).start();}
