    boolean isToday(Calendar date){Calendar today=Calendar.getInstance();return dateKey(date).equals(dateKey(today));}
    String dateKeyForMillis(long millis){Calendar c=Calendar.getInstance();c.setTimeInMillis(millis);return dateKey(c);}
    void rebuildActivityCounts(){if(!activityCountsDirty)return;activityCountsByDate.clear();for(Note item:notes){String key=dateKeyForMillis(item.updatedAt);activityCountsByDate.put(key,(activityCountsByDate.containsKey(key)?activityCountsByDate.get(key):0)+1);}for(TimeEntry item:timeline)activityCountsByDate.put(item.date,(activityCountsByDate.containsKey(item.date)?activityCountsByDate.get(item.date):0)+1);activityCountsDirty=false;}
    int activityCount(Calendar day){rebuildActivityCounts();return (activityCountsByDate.containsKey(dateKey(day))?activityCountsByDate.get(dateKey(day)):0);}
