    String displayLabel(String label){return label==null?"":label.replace("#","").trim();}
    String labelLeafName(String label){if(label==null)return "";int split=label.lastIndexOf('/');return displayLabel(split>=0?label.substring(split+1):label);}
    boolean isLabelInScope(String label,String scope){return scope==null||scope.isEmpty()||label.equals(scope)||label.startsWith(scope+"/");}
    boolean noteHasLabelInScope(Note item,String scope){if(scope==null||scope.isEmpty())return true;for(String tag:item.tags)if(isLabelInScope(tag,scope))return true;return false;}
    void normalizeLabelHierarchy(){ArrayList<String> paths=new ArrayList<>(labels);for(Note item:notes)paths.addAll(item.tags);for(Note item:trash)paths.addAll(item.tags);for(String path:paths)ensureLabelPath(path);for(Note item:notes)normalizeNoteTags(item);for(Note item:trash)normalizeNoteTags(item);}
    void normalizeNoteTags(Note item){LinkedHashSet<String> paths=new LinkedHashSet<>();for(String path:item.tags){if(path==null)continue;String clean=path.trim().replaceAll("^/+|/+$","").replaceAll("/{2,}","/");if(!clean.isEmpty()){paths.add(clean);ensureLabelPath(clean);}}ArrayList<String> candidates=new ArrayList<>(paths);for(String path:candidates)for(String other:candidates)if(!path.equals(other)&&other.startsWith(path+"/")){paths.remove(path);break;}item.tags.clear();item.tags.addAll(paths);}
    String folderSummary(String scope){int tagCount=0,noteCount=0,charCount=0;for(String label:labels)if(isLabelInScope(label,scope))tagCount++;for(Note item:notes)if(noteHasLabelInScope(item,scope)){noteCount++;String value=(item.title==null?"":item.title)+noteContent(item);for(int i=0;i<value.length();i++)if(!Character.isWhitespace(value.charAt(i)))charCount++;}String amount=charCount>=10000?String.format(Locale.ROOT,"%.1f万字",charCount/10000.0):charCount>=1000?String.format(Locale.ROOT,"%.1fk字",charCount/1000.0):charCount+"字";return "共 "+tagCount+" 个标签，"+noteCount+" 条笔记，"+amount;}
    String displayTags(List<String> source){StringBuilder out=new StringBuilder();for(String label:source){if(out.length()>0)out.append(" · ");out.append(displayLabel(label));}return out.toString();}
