    void toggleBlockSelection(){
        blockSelectionMode=!blockSelectionMode;selectedBlocks.clear();
        if(board!=null){board.selectedBlock=null;board.selectedConnection=null;board.resizeSelected=null;board.invalidate();}
        if(root.getChildCount()>2)root.removeViewAt(root.getChildCount()-1);
        if(blockSelectionMode)buildBlockActions();else bottomNav(0);
        if(blockSelectButton!=null){blockSelectButton.setText(blockSelectionMode?"完成":"☑");blockSelectButton.setTextSize(blockSelectionMode?13:24);}
    }
    void buildBlockActions(){blockActions=row();blockActions.setPadding(dp(12),dp(8),dp(12),dp(8));blockActions.setBackgroundColor(Color.WHITE);root.addView(blockActions,new LinearLayout.LayoutParams(-1,dp(62)));
        String[] names={"添加到","将格子放在一起","按顺序合并","删除"};for(int i=0;i<names.length;i++){final int action=i;TextView item=text(names[i],12,muted,true);item.setGravity(Gravity.CENTER);item.setMaxLines(2);item.setPadding(dp(3),0,dp(3),0);blockActions.addView(item,new LinearLayout.LayoutParams(0,-1,1));item.setOnClickListener(v->{if(selectedBlocks.isEmpty())return;if(action==0)showBlockDestinations();else if(action==1)groupSelectedBlocks();else if(action==2)mergeSelectedBlocks();else styledConfirm("删除片段","确定删除选中的 "+selectedBlocks.size()+" 个文字格子吗？","取消",null,"删除",()->deleteSelectedBlocks());});}updateBlockActions();}
    void updateBlockActions(){selectedBlocks.retainAll(note.blocks);if(blockActions==null)return;for(int i=0;i<blockActions.getChildCount();i++){TextView item=(TextView)blockActions.getChildAt(i);item.setEnabled(!selectedBlocks.isEmpty());item.setTextColor(selectedBlocks.isEmpty()?muted:ink);}}
    ArrayList<Block> orderedSelection(){ArrayList<Block> result=new ArrayList<>(selectedBlocks);result.retainAll(note.blocks);result.sort((a,b)->Integer.compare(a.order,b.order));return result;}
    void refreshBlockSelection(){selectedBlocks.clear();updateBlockActions();if(board!=null){board.requestLayout();board.invalidate();}}
    void deleteSelectedBlocks(){saveUndo();HashSet<String> ids=new HashSet<>();for(Block b:selectedBlocks)ids.add(b.id);note.blocks.removeAll(selectedBlocks);note.connections.removeIf(c->ids.contains(c.fromId)||ids.contains(c.toId));normalizeBlockOrder();note.updatedAt=System.currentTimeMillis();persist();refreshBlockSelection();}
    boolean blocksIntersect(Block a,Block b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;}
    void groupSelectedBlocks(){
        if(board==null)return;flushPendingBlockPersist();ArrayList<Block> chosen=orderedSelection();if(chosen.size()<2){toast("请至少选择两个文字格子");return;}
        for(Block block:note.blocks)board.sizeBlock(block,board.getWidth());
        chosen.sort((a,b)->a.y==b.y?Integer.compare(a.x,b.x):Integer.compare(a.y,b.y));
        saveUndo();Block anchor=chosen.get(0);int startX=anchor.x,row=anchor.y;
        int columns=Math.max(4,(int)((board.getWidth()-dp(20))/board.cell));
        // Pack whole blocks, without changing their text, dimensions, IDs or links.
        for(Block block:chosen){block.x=Math.max(0,Math.min(startX,columns-block.w));block.y=row;row+=block.h;}
        ArrayList<Block> remaining=new ArrayList<>(note.blocks);remaining.removeAll(chosen);
        remaining.sort((a,b)->a.y==b.y?Integer.compare(a.x,b.x):Integer.compare(a.y,b.y));
        ArrayList<Block> placed=new ArrayList<>(chosen);
        for(Block block:remaining){boolean collision;do{collision=false;for(Block occupied:placed)if(blocksIntersect(block,occupied)){block.y=occupied.y+occupied.h;collision=true;}}while(collision);placed.add(block);}
        ArrayList<Block> readingOrder=new ArrayList<>(note.blocks);readingOrder.sort((a,b)->a.y==b.y?Integer.compare(a.x,b.x):Integer.compare(a.y,b.y));for(int i=0;i<readingOrder.size();i++)readingOrder.get(i).order=i;
        note.updatedAt=System.currentTimeMillis();persist();updateBlockActions();board.requestLayout();board.invalidate();
    }
    void mergeSelectedBlocks(){ArrayList<Block> chosen=orderedSelection();if(chosen.size()<2){toast("请至少选择两个文字格子");return;}saveUndo();Block first=chosen.get(0);StringBuilder value=new StringBuilder();HashSet<String> removed=new HashSet<>();for(Block b:chosen){if(value.length()>0)value.append("\n\n");value.append(b.text);if(b!=first){removed.add(b.id);note.blocks.remove(b);}}first.text=value.toString();first.merged=true;first.sized=false;note.connections.removeIf(c->removed.contains(c.fromId)||removed.contains(c.toId));
        if(board!=null){board.sizeBlock(first,board.getWidth());int bottom=first.y+first.h;ArrayList<Block> rest=new ArrayList<>(note.blocks);rest.sort((a,b)->a.y==b.y?Integer.compare(a.x,b.x):Integer.compare(a.y,b.y));for(Block b:rest)if(b!=first&&b.y>=first.y){b.y=Math.max(b.y,bottom+1);bottom=b.y+b.h;}}
        normalizeBlockOrder();note.updatedAt=System.currentTimeMillis();persist();refreshBlockSelection();}
