        ListView list=new ListView(this);list.setDividerHeight(dp(1));panel.addView(list,new LinearLayout.LayoutParams(-1,0,1));ArrayList<Note> ordered=new ArrayList<>(notes);ordered.remove(note);ordered.sort((a,b)->Long.compare(b.updatedAt,a.updatedAt));ArrayList<Note> visible=new ArrayList<>();
        BaseAdapter adapter=new BaseAdapter(){public int getCount(){return visible.size();}public Object getItem(int position){return visible.get(position);}public long getItemId(int position){return position;}public View getView(int position,View reuse,ViewGroup parent){
            Note item=visible.get(position);String q=search.getText().toString().trim();LinearLayout entry=new LinearLayout(MainActivity.this);entry.setOrientation(LinearLayout.VERTICAL);entry.setPadding(dp(22),dp(12),dp(22),dp(12));TextView heading=text(item.title.trim().isEmpty()?"无标题":item.title,15,ink,true);if(!q.isEmpty())heading.setText(highlightGray(heading.getText().toString(),q));entry.addView(heading,new LinearLayout.LayoutParams(-1,-2));
            String body=searchPreview(item,q);if(!body.isEmpty()){TextView snippet=text(body,13,muted,false);snippet.setMaxLines(3);snippet.setEllipsize(android.text.TextUtils.TruncateAt.END);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,-2);bp.topMargin=dp(4);entry.addView(snippet,bp);if(!q.isEmpty())snippet.setText(highlightGray(body,q));}TextView date=text(dateLabel(item.updatedAt),11,0xFFB0B0B0,false);LinearLayout.LayoutParams dateParams=new LinearLayout.LayoutParams(-1,dp(20));dateParams.topMargin=dp(4);entry.addView(date,dateParams);return entry;}};list.setAdapter(adapter);Runnable filter=()->{visible.clear();String q=search.getText().toString().trim();for(Note n:ordered)if(q.isEmpty()||contains(n.title,q)||contains(noteContent(n),q))visible.add(n);adapter.notifyDataSetChanged();};search.addTextChangedListener(watch(v->filter.run()));filter.run();list.setOnItemClickListener((a,v,position,id)->chooseBlockTransfer(page,visible.get(position)));page.setContentView(panel);page.show();page.getWindow().setLayout(-1,-1);
