    void chooseBlockTransfer(Dialog page,Note target){styledOptions("请选择笔记移动方式",target.title.trim().isEmpty()?"无标题":target.title,Arrays.asList("复制","移动","取消"),index->{if(index<2)transferSelectedBlocks(page,target,index==1);},null,null);}
    void transferSelectedBlocks(Dialog page,Note target,boolean move){
        flushPendingBlockPersist();ArrayList<Block> chosen=orderedSelection();if(chosen.isEmpty())return;Note source=note;ArrayList<Block> copies=new ArrayList<>();HashMap<String,String> ids=new HashMap<>();ArrayList<Connection> links=new ArrayList<>();
        Dialog progress=new Dialog(this);LinearLayout progressPanel=new LinearLayout(this);progressPanel.setOrientation(1);progressPanel.setPadding(dp(24),dp(20),dp(24),dp(20));progressPanel.setBackground(shape(Color.WHITE,18));TextView label=text("正在整理片段…",16,ink,true);progressPanel.addView(label);ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(chosen.size());progressPanel.addView(bar,new LinearLayout.LayoutParams(dp(250),dp(24)));progress.setContentView(progressPanel);progress.setCancelable(false);if(chosen.size()>30){progress.show();progress.getWindow().setBackgroundDrawableResource(android.R.color.transparent);}
        Runnable work=new Runnable(){int index=0,row=0;public void run(){try{int end=Math.min(index+20,chosen.size());while(index<end){Block original=chosen.get(index++);Block copy=new Block(original.json());copy.id=UUID.randomUUID().toString();copy.x=0;copy.y=row;copy.order=copies.size();copy.sized=false;board.sizeBlock(copy,board.getWidth());row+=copy.h+1;copies.add(copy);ids.put(original.id,copy.id);}bar.setProgress(index);if(index<chosen.size()){saveHandler.post(this);return;}
            for(Connection c:source.connections)if(ids.containsKey(c.fromId)&&ids.containsKey(c.toId)){Connection copy=new Connection(ids.get(c.fromId),c.fromSide,ids.get(c.toId),c.toSide);copy.color=c.color;links.add(copy);}
            if(!target.text.trim().isEmpty()){Block existing=new Block();existing.text=target.text;existing.order=target.blocks.size();existing.y=0;for(Block b:target.blocks)existing.y=Math.max(existing.y,b.y+b.h+1);board.sizeBlock(existing,board.getWidth());target.blocks.add(existing);target.text="";}
            for(Block b:target.blocks){b.y+=row;b.order+=copies.size();}target.blocks.addAll(0,copies);target.connections.addAll(links);target.updatedAt=System.currentTimeMillis();if(!notes.contains(target))notes.add(0,target);
            if(move){source.blocks.removeAll(chosen);source.connections.removeIf(c->ids.containsKey(c.fromId)||ids.containsKey(c.toId));normalizeBlockOrder();source.updatedAt=target.updatedAt;}undo.clear();redo.clear();refreshUndoButtons();persist();refreshBlockSelection();progress.dismiss();page.dismiss();toast(move?"已移动到目标笔记":"已复制到目标笔记");
        }catch(Exception e){progress.dismiss();toast("操作失败，请重试");}}};saveHandler.post(work);
    }
