    void deleteBlock(Block target){Note owner=note;int index=owner.blocks.indexOf(target);if(index<0)return;ArrayList<Connection> removedLinks=new ArrayList<>();for(Connection connection:new ArrayList<>(owner.connections))if(connection.fromId.equals(target.id)||connection.toId.equals(target.id)){owner.connections.remove(connection);removedLinks.add(connection);}owner.blocks.remove(index);owner.updatedAt=System.currentTimeMillis();persist();if(note==owner&&screen==4)renderContent();showUndoSnackbar("已删除笔记",()->{owner.blocks.add(Math.min(index,owner.blocks.size()),target);owner.connections.addAll(removedLinks);owner.updatedAt=System.currentTimeMillis();persist();if(note==owner&&screen==4)renderContent();});}
    int nextY(){int y=0;for(Block b:note.blocks)y=Math.max(y,b.y+b.h);return y;}
    void normalizeBlockOrder(){ArrayList<Block> sorted=new ArrayList<>(note.blocks);sorted.sort((a,b)->Integer.compare(a.order,b.order));for(int i=0;i<sorted.size();i++)sorted.get(i).order=i;}
    int nextBlockOrder(){int next=0;for(Block b:note.blocks)next=Math.max(next,b.order+1);return next;}
    void beginEditorSession(){if(note==null)return;if(!historyNoteId.equals(note.id)){undo.clear();redo.clear();historyNoteId=note.id;}}
    void finishEditorSession(){if(screen==4){flushPendingBlockPersist();persist();}undo.clear();redo.clear();historyNoteId="";selectionTextPreview=false;selectionPreviewText="";blockSelectionMode=false;selectedBlocks.clear();dismissUndoSnackbar();}
    String historySnapshot()throws Exception{JSONObject state=new JSONObject();state.put("note",note.json());state.put("linear",isLinear);return state.toString();}
    void saveUndo(){if(screen!=4||note==null)return;beginEditorSession();try{String snapshot=historySnapshot();if(undo.isEmpty()||!undo.peek().equals(snapshot))undo.push(snapshot);if(undo.size()>40)undo.removeLast();redo.clear();refreshUndoButtons();}catch(Exception ignored){}}
    void refreshUndoButtons(){if(screen!=4||root==null)return;View undoButton=root.findViewWithTag("editor-undo");if(undoButton!=null)styleUndoButton(undoButton);View redoButton=root.findViewWithTag("editor-redo");if(redoButton!=null){boolean enabled=!selectionTextPreview&&note!=null&&historyNoteId.equals(note.id)&&!redo.isEmpty();redoButton.setEnabled(enabled);redoButton.setAlpha(enabled?1f:.3f);}LinearLayout footer=root.findViewWithTag("editor-footer");if(footer!=null&&footer.getChildCount()>0)styleUndoButton(footer.getChildAt(0));}
    void undo(){restoreHistory(undo,redo);}
    void redo(){restoreHistory(redo,undo);}
    void restoreHistory(ArrayDeque<String> from,ArrayDeque<String> to){
        if(screen!=4||selectionTextPreview||note==null||!historyNoteId.equals(note.id)||from.isEmpty())return;flushPendingBlockPersist();
        try{JSONObject state=new JSONObject(from.peek());Note restored=new Note(state.getJSONObject("note"));if(!restored.id.equals(note.id)||trash.contains(note)){undo.clear();redo.clear();refreshUndoButtons();return;}
            String before=historySnapshot();int index=-1;for(int i=0;i<notes.size();i++)if(notes.get(i).id.equals(restored.id)){index=i;break;}
            from.pop();to.push(before);if(index>=0)notes.set(index,restored);note=restored;current=index;isLinear=state.optBoolean("linear",false);selectedBlocks.clear();blockSelectionMode=false;note.updatedAt=System.currentTimeMillis();persist();int scroll=boardScroll==null?0:boardScroll.getScrollY();build();if(!isLinear&&boardScroll!=null){ScrollView target=boardScroll;target.post(()->target.scrollTo(0,scroll));}refreshUndoButtons();
        }catch(Exception e){toast("无法恢复这一步操作");}
    }
