    void trashNote(){flushPendingBlockPersist();finishEditorSession();Note removed=note;if(noteIsBlank(removed)){notes.remove(removed);if(notes.isEmpty()){note=new Note();current=0;}else{current=0;note=notes.get(0);}persist();buildHome();return;}int oldIndex=notes.indexOf(removed);notes.remove(removed);trash.add(0,removed);if(notes.isEmpty()){note=new Note();current=0;}else{current=Math.min(current,notes.size()-1);note=notes.get(current);}persist();buildHome();showUndoSnackbar("已删除笔记",()->{trash.remove(removed);notes.add(Math.min(oldIndex,notes.size()),removed);current=notes.indexOf(removed);note=removed;persist();buildHome();});}
