    void closeDrawer(){sideTagAdapter=null;if(sideDrawerOverlay!=null){View overlay=sideDrawerOverlay;sideDrawerOverlay=null;if(overlay.getParent() instanceof ViewGroup)((ViewGroup)overlay.getParent()).removeView(overlay);}}
    class DrawerLayer extends FrameLayout{View scrim,drawer;int drawerWidth;float downX,downY;boolean dragging;DrawerLayer(Context context){super(context);setClickable(true);}public boolean onInterceptTouchEvent(MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN){downX=e.getX();downY=e.getY();dragging=false;return false;}if(e.getActionMasked()==MotionEvent.ACTION_MOVE&&!dragging){float dx=e.getX()-downX,dy=e.getY()-downY;if(downX<=drawerWidth+dp(8)&&dx<-dp(8)&&Math.abs(dx)>Math.abs(dy)*1.2f){dragging=true;return true;}}return dragging;}public boolean onTouchEvent(MotionEvent e){if(!dragging)return super.onTouchEvent(e);if(e.getActionMasked()==MotionEvent.ACTION_MOVE){float dx=e.getX()-downX;float tx=Math.max(-drawerWidth,Math.min(0,dx));drawer.setTranslationX(tx);if(scrim!=null)scrim.setAlpha(Math.max(0,1f+tx/drawerWidth));return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL){float tx=drawer.getTranslationX();dragging=false;if(e.getActionMasked()==MotionEvent.ACTION_UP&&tx<=-drawerWidth*.28f){closeDrawer();}else{drawer.animate().translationX(0).setDuration(180).start();if(scrim!=null)scrim.animate().alpha(1f).setDuration(180).start();}return true;}return true;}}
    void tagPicker(){showLabelPicker(true);}
    boolean isInside(View child,View parent){View current=child;while(current!=null){if(current==parent)return true;android.view.ViewParent owner=current.getParent();current=owner instanceof View?(View)owner:null;}return false;}
    void showLabelTools(View anchor){String[] actions={"新建标签","搜索标签"};boolean editing=screen==4&&isInside(anchor,body);LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(8),dp(6),dp(8),dp(6));panel.setBackground(shape(Color.WHITE,14));PopupWindow popup=new PopupWindow(panel,dp(176),WindowManager.LayoutParams.WRAP_CONTENT,true);popup.setBackgroundDrawable(shape(Color.WHITE,14));popup.setOutsideTouchable(true);popup.setElevation(dp(8));for(int i=0;i<actions.length;i++){final int index=i;TextView action=text(actions[i],14,ink,false);action.setPadding(dp(12),0,dp(8),0);panel.addView(action,new LinearLayout.LayoutParams(-1,dp(46)));action.setOnClickListener(v->{popup.dismiss();if(index==0)addLabel(editing);else showLabelPicker(editing);});}popup.showAsDropDown(anchor,anchor.getWidth()-dp(176),dp(2));}
    void showLabelPicker(boolean selectForNote){Dialog dialog=new Dialog(this);LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(20),dp(18),dp(20),dp(16));panel.setBackground(shape(Color.WHITE,20));LinearLayout heading=row();TextView title=text(selectForNote?"添加标签":"搜索标签",18,ink,true);heading.addView(title,new LinearLayout.LayoutParams(0,dp(38),1));TextView close=text("×",24,muted,false);close.setGravity(Gravity.CENTER);heading.addView(close,new LinearLayout.LayoutParams(dp(36),dp(38)));panel.addView(heading);close.setOnClickListener(v->dialog.dismiss());EditText query=new EditText(this);query.setSingleLine(true);query.setTextSize(15);query.setTextColor(ink);query.setHint("搜索标签");query.setPadding(dp(12),0,dp(12),0);query.setBackground(shape(0xFFF3F3F3,12));LinearLayout.LayoutParams qp=new LinearLayout.LayoutParams(-1,dp(44));qp.topMargin=dp(8);panel.addView(query,qp);ScrollView scroll=new ScrollView(this);LinearLayout.LayoutParams slp=new LinearLayout.LayoutParams(-1,dp(280));slp.topMargin=dp(8);panel.addView(scroll,slp);LinearLayout results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);scroll.addView(results);Runnable refresh=()->{results.removeAllViews();String q=query.getText().toString().trim();for(String label:labels){if(!contains(label,q))continue;boolean selected=note.tags.contains(label);LinearLayout option=row();option.setPadding(dp(12),0,dp(4),0);TextView labelName=text(displayLabel(label),15,ink,false);option.addView(labelName,new LinearLayout.LayoutParams(0,-1,1));TextView action=text(selectForNote?(selected?"✓":"＋"):"›",selectForNote?20:24,selected?0xFF4A8A62:ink,true);action.setGravity(Gravity.CENTER);option.addView(action,new LinearLayout.LayoutParams(dp(44),dp(44)));results.addView(option,new LinearLayout.LayoutParams(-1,dp(44)));View.OnClickListener choose=v->{if(selectForNote){if(note.tags.contains(label))note.tags.remove(label);else note.tags.add(label);persist();dialog.dismiss();build();}else{activeTagFilter=label;dialog.dismiss();closeDrawer();openSearch("");}};labelName.setOnClickListener(choose);action.setContentDescription(selected?"移除标签":"添加标签");action.setOnClickListener(choose);}if(results.getChildCount()==0){TextView empty=text("没有匹配的标签",14,muted,false);results.addView(empty,new LinearLayout.LayoutParams(-1,dp(44)));}};query.addTextChangedListener(watch(v->refresh.run()));refresh.run();TextView create=text("＋  新建标签",14,ink,true);create.setGravity(Gravity.CENTER);create.setBackground(shape(0xFFF1F1F1,12));LinearLayout.LayoutParams createParams=new LinearLayout.LayoutParams(-1,dp(44));createParams.topMargin=dp(10);panel.addView(create,createParams);create.setOnClickListener(v->{dialog.dismiss();addLabel();});dialog.setContentView(panel);Window window=dialog.getWindow();if(window!=null){window.setBackgroundDrawableResource(android.R.color.transparent);window.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-dp(32),dp(400)),WindowManager.LayoutParams.WRAP_CONTENT);}dialog.show();if(window!=null)window.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-dp(32),dp(400)),WindowManager.LayoutParams.WRAP_CONTENT);}
    void toggleTagPin(String label){if(pinnedLabels.contains(label))pinnedLabels.remove(label);else pinnedLabels.add(label);persist();refreshSideTagList();}
    void toggleNotePin(Note item){item.pinned=!item.pinned;item.updatedAt=System.currentTimeMillis();persist();if(screen==0)buildHome();else if(screen==3)buildSearch(searchInput.getText().toString());}
    void showNoteActions(View anchor,Note item){LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(8),dp(6),dp(8),dp(6));panel.setBackground(shape(Color.WHITE,14));PopupWindow popup=new PopupWindow(panel,dp(200),WindowManager.LayoutParams.WRAP_CONTENT,true);popup.setBackgroundDrawable(shape(Color.WHITE,14));popup.setOutsideTouchable(true);popup.setElevation(dp(8));String[] items={item.pinned?"取消置顶":"置顶","复制全文","分享","更改记本","删除"};Runnable[] actions={()->toggleNotePin(item),()->copyNoteContent(item),()->shareNote(item),()->assignNotebook(item),()->moveNoteToTrash(item)};for(int i=0;i<items.length;i++){final int index=i;TextView row=text(items[i],14,index==items.length-1?0xFFE44332:ink,false);row.setPadding(dp(12),0,dp(8),0);panel.addView(row,new LinearLayout.LayoutParams(-1,dp(46)));row.setOnClickListener(v->{popup.dismiss();actions[index].run();});}popup.showAsDropDown(anchor,anchor.getWidth()-dp(200),dp(2));}
    void moveNoteToTrash(Note item){int position=notes.indexOf(item);if(position<0)return;int returnScreen=screen;String searchQuery=returnScreen==3&&searchInput!=null?searchInput.getText().toString():"";notes.remove(position);trash.add(0,item);persist();if(returnScreen==0)buildHomeKeepingPosition();else if(returnScreen==3)buildSearch(searchQuery);else if(returnScreen==2)buildTimeline();else refreshVisibleScreen();showUndoSnackbar("已移入回收站",()->{trash.remove(item);notes.add(Math.max(0,Math.min(position,notes.size())),item);persist();if(returnScreen==0)buildHomeKeepingPosition();else if(returnScreen==3)buildSearch(searchQuery);else if(returnScreen==2)buildTimeline();else refreshVisibleScreen();});}
    void copyNoteContent(Note item){((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("碎忆",markdownPlainText(noteContent(item))));toast("已复制全文");}
    void shareNote(Note item){Intent share=new Intent(Intent.ACTION_SEND);share.setType("text/plain");share.putExtra(Intent.EXTRA_TEXT,markdownPlainText(noteContent(item)));share.putExtra(Intent.EXTRA_SUBJECT,item.title.trim().isEmpty()?"碎忆笔记":item.title);startActivity(Intent.createChooser(share,"分享笔记"));}
    void showTagActions(View anchor,String label){boolean pinned=pinnedLabels.contains(label);String[] choices={pinned?"取消置顶":"置顶","新建标签","搜索标签","删除标签","删除标签及笔记"};Runnable[] actions={()->toggleTagPin(label),()->addLabel(false),()->showLabelPicker(false),()->styledConfirm("删除标签","删除“"+label+"”标签？相关笔记会保留。","取消",null,"删除标签",()->deleteTag(label)),()->styledConfirm("删除标签及笔记","删除“"+label+"”标签，并将使用此标签的笔记移入回收站？","取消",null,"删除",()->deleteTagAndNotes(label))};LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(8),dp(6),dp(8),dp(6));panel.setBackground(shape(Color.WHITE,14));PopupWindow popup=new PopupWindow(panel,dp(224),WindowManager.LayoutParams.WRAP_CONTENT,true);popup.setBackgroundDrawable(shape(Color.WHITE,14));popup.setOutsideTouchable(true);popup.setElevation(dp(8));for(int i=0;i<choices.length;i++){final int index=i;TextView choice=text(choices[i],14,i==4?0xFFE44332:ink,false);choice.setPadding(dp(12),0,dp(8),0);panel.addView(choice,new LinearLayout.LayoutParams(-1,dp(44)));choice.setOnClickListener(v->{popup.dismiss();actions[index].run();});if(i==2){View divider=new View(this);divider.setBackgroundColor(line);panel.addView(divider,new LinearLayout.LayoutParams(-1,dp(1)));}}popup.showAsDropDown(anchor,anchor.getWidth()-dp(224),dp(2));}
    void refreshVisibleScreen(){if(screen==5)buildMy();else if(screen==6)buildWalk();else if(screen==4)build();else if(screen==3)buildSearch(searchInput.getText().toString());else if(screen==2)buildTimeline();else buildHome();}
    void deleteTag(String label){int index=labels.indexOf(label);if(index<0)return;boolean wasPinned=pinnedLabels.remove(label);ArrayList<Note> tagged=new ArrayList<>();for(Note item:notes)if(item.tags.remove(label))tagged.add(item);labels.remove(index);closeDrawer();persist();refreshVisibleScreen();showUndoSnackbar("已删除标签",()->{labels.add(Math.min(index,labels.size()),label);if(wasPinned)pinnedLabels.add(label);for(Note item:tagged)if(!item.tags.contains(label))item.tags.add(label);persist();refreshVisibleScreen();});}
    void deleteTagAndNotes(String label){int labelIndex=labels.indexOf(label);if(labelIndex<0)return;boolean wasPinned=pinnedLabels.remove(label);ArrayList<Note> removed=new ArrayList<>();HashMap<Note,Integer> positions=new HashMap<>();for(int i=notes.size()-1;i>=0;i--){Note item=notes.get(i);if(item.tags.contains(label)){positions.put(item,i);item.tags.remove(label);notes.remove(i);trash.add(0,item);removed.add(item);}}boolean currentRemoved=note!=null&&removed.contains(note);labels.remove(labelIndex);closeDrawer();if(currentRemoved){if(notes.isEmpty()){note=new Note();current=0;}else{current=0;note=notes.get(0);}}persist();if(screen==4&&currentRemoved)buildHome();else refreshVisibleScreen();showUndoSnackbar("已删除标签及笔记",()->{labels.add(Math.min(labelIndex,labels.size()),label);if(wasPinned)pinnedLabels.add(label);removed.sort((a,b)->Integer.compare(positions.get(a),positions.get(b)));for(Note item:removed){trash.remove(item);if(!item.tags.contains(label))item.tags.add(label);notes.add(Math.min(positions.get(item),notes.size()),item);}if(!removed.isEmpty()){note=removed.get(0);current=notes.indexOf(note);}persist();refreshVisibleScreen();});}
    void addLabel(){addLabel(screen==4);}
    void addLabel(boolean selectAfter){EditText e=dialogInput("标签名称",null,1);styledPanel("新建标签",null,e,"取消",null,"添加",()->{String s=e.getText().toString().trim();if(!s.isEmpty()&&!labels.contains(s)){labels.add(s);if(selectAfter&&!note.tags.contains(s))note.tags.add(s);persist();if(screen==4)build();else refreshVisibleScreen();}});}
    void showTrash(){finishEditorSession();closeDrawer();trashSelectionMode=false;selectedTrash.clear();trashScrollY=0;buildTrashKeepingPosition();}
    void buildTrashKeepingPosition(){
        screen=8;root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(bg);setContentView(root);LinearLayout header=row();header.setPadding(dp(16),dp(8),dp(16),dp(8));root.addView(header,new LinearLayout.LayoutParams(-1,dp(58)));header.addView(iconButton("返回",this::handleBack),new LinearLayout.LayoutParams(dp(40),dp(42)));TextView title=text("回收站",20,ink,true);header.addView(title,new LinearLayout.LayoutParams(0,-1,1));TextView select=text(trashSelectionMode?"完成":"选择",14,ink,true);select.setGravity(Gravity.CENTER);header.addView(select,new LinearLayout.LayoutParams(dp(50),dp(42)));select.setOnClickListener(v->{trashSelectionMode=!trashSelectionMode;selectedTrash.clear();buildTrashKeepingPosition();});
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout list=new LinearLayout(this);list.setOrientation(1);list.setPadding(dp(18),dp(8),dp(18),dp(24));scroll.addView(list);selectedTrash.retainAll(trash);
        if(trash.isEmpty())emptyHome(list,"回收站是空的","删除的笔记会显示在这里。");
        for(Note item:new ArrayList<>(trash)){
            LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(18),dp(12),dp(12),dp(16));card.setBackground(shape(selectedTrash.contains(item)?0xFFEAECEF:Color.WHITE,18));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=dp(12);list.addView(card,cp);LinearLayout heading=row();card.addView(heading,new LinearLayout.LayoutParams(-1,dp(34)));TextView mark=text(selectedTrash.contains(item)?"☑":"□",20,ink,true);if(trashSelectionMode)heading.addView(mark,new LinearLayout.LayoutParams(dp(30),-1));TextView label=text(item.title.trim().isEmpty()?"无标题":item.title,17,ink,true);label.setSingleLine(true);label.setEllipsize(android.text.TextUtils.TruncateAt.END);heading.addView(label,new LinearLayout.LayoutParams(0,-1,1));FrameLayout more=new FrameLayout(this);more.setContentDescription("回收站笔记操作");more.addView(new IconGlyph("moreHorizontal",muted),new FrameLayout.LayoutParams(dp(22),dp(22),Gravity.CENTER));heading.addView(more,new LinearLayout.LayoutParams(dp(36),dp(34)));more.setOnClickListener(v->showTrashActions(more,item));
            TextView snippet=text(noteContent(item),14,ink,false);snippet.setMaxLines(3);snippet.setEllipsize(android.text.TextUtils.TruncateAt.END);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,-2);sp.topMargin=dp(6);card.addView(snippet,sp);TextView date=text(dateLabel(item.updatedAt),12,muted,false);LinearLayout.LayoutParams dateParams=new LinearLayout.LayoutParams(-1,dp(24));dateParams.topMargin=dp(8);card.addView(date,dateParams);
            if(trashSelectionMode)card.setOnClickListener(v->{if(!selectedTrash.remove(item))selectedTrash.add(item);mark.setText(selectedTrash.contains(item)?"☑":"□");card.setBackground(shape(selectedTrash.contains(item)?0xFFEAECEF:Color.WHITE,18));updateTrashRestoreButton();});else{GestureDetector gestures=new GestureDetector(this,new GestureDetector.SimpleOnGestureListener(){public boolean onDown(MotionEvent e){return true;}public boolean onDoubleTap(MotionEvent e){buildTrashReader(item);return true;}});card.setOnTouchListener((v,e)->gestures.onTouchEvent(e));}
        }
        if(trashSelectionMode){LinearLayout actions=row();actions.setPadding(dp(18),dp(8),dp(18),dp(8));actions.setBackgroundColor(Color.WHITE);trashRestoreButton=text("恢复已选笔记",15,ink,true);trashRestoreButton.setGravity(Gravity.CENTER);actions.addView(trashRestoreButton,new LinearLayout.LayoutParams(-1,dp(46)));root.addView(actions,new LinearLayout.LayoutParams(-1,dp(62)));trashRestoreButton.setOnClickListener(v->restoreTrashNotes(new ArrayList<>(selectedTrash)));updateTrashRestoreButton();}
        int position=trashScrollY;scroll.post(()->scroll.scrollTo(0,position));scroll.setOnScrollChangeListener((v,x,y,oldX,oldY)->trashScrollY=y);
    }
    void updateTrashRestoreButton(){if(trashRestoreButton!=null){trashRestoreButton.setEnabled(!selectedTrash.isEmpty());trashRestoreButton.setTextColor(selectedTrash.isEmpty()?muted:ink);trashRestoreButton.setText("恢复已选笔记（"+selectedTrash.size()+"）");}}
    void restoreTrashNotes(ArrayList<Note> chosen){int count=0;for(Note item:chosen)if(trash.remove(item)){boolean exists=false;for(Note active:notes)if(active.id.equals(item.id)){exists=true;break;}if(!exists)notes.add(0,item);selectedTrash.remove(item);count++;}persist();buildTrashKeepingPosition();toast("已恢复 "+count+" 篇笔记");}
    void showTrashActions(View anchor,Note item){LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(dp(8),dp(6),dp(8),dp(6));panel.setBackground(shape(Color.WHITE,14));PopupWindow popup=new PopupWindow(panel,dp(180),-2,true);popup.setBackgroundDrawable(shape(Color.WHITE,14));popup.setOutsideTouchable(true);popup.setElevation(dp(8));TextView restore=text("恢复",14,ink,false),delete=text("彻底删除",14,0xFFE44332,false);for(TextView action:new TextView[]{restore,delete}){action.setPadding(dp(14),0,dp(10),0);panel.addView(action,new LinearLayout.LayoutParams(-1,dp(48)));}restore.setOnClickListener(v->{popup.dismiss();restoreTrashNotes(new ArrayList<>(Collections.singletonList(item)));});delete.setOnClickListener(v->{popup.dismiss();styledConfirm("彻底删除","永久删除这篇笔记？此操作无法撤销。","取消",null,"彻底删除",()->{trash.remove(item);selectedTrash.remove(item);persist();buildTrashKeepingPosition();});});popup.showAsDropDown(anchor,anchor.getWidth()-dp(180),dp(2));}
    void buildTrashReader(Note item){if(!trash.contains(item)){buildTrashKeepingPosition();return;}trashViewingNote=item;screen=9;root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(bg);setContentView(root);LinearLayout header=row();header.setPadding(dp(16),dp(8),dp(16),dp(8));root.addView(header,new LinearLayout.LayoutParams(-1,dp(58)));header.addView(iconButton("返回",this::handleBack),new LinearLayout.LayoutParams(dp(42),dp(42)));TextView title=text("回收站 · 只读",18,ink,true);header.addView(title,new LinearLayout.LayoutParams(0,-1,1));FrameLayout more=iconButton("更多",()->{});header.addView(more,new LinearLayout.LayoutParams(dp(42),dp(42)));more.setOnClickListener(v->showTrashActions(more,item));ScrollView scroll=new ScrollView(this);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout page=new LinearLayout(this);page.setOrientation(1);page.setPadding(dp(24),dp(16),dp(24),dp(32));scroll.addView(page);TextView heading=text(item.title.trim().isEmpty()?"无标题":item.title,23,ink,true);page.addView(heading,new LinearLayout.LayoutParams(-1,-2));TextView body=text(noteContent(item),16,ink,false);body.setLineSpacing(dp(4),1);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,-2);bp.topMargin=dp(24);page.addView(body,bp);}

