    SecretKey storageKey()throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);String alias="suiyi_data_key_v1";if(store.containsAlias(alias))return (SecretKey)store.getKey(alias,null);KeyGenParameterSpec spec=new KeyGenParameterSpec.Builder(alias,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setRandomizedEncryptionRequired(true).build();javax.crypto.KeyGenerator generator=javax.crypto.KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");generator.init(spec);return generator.generateKey();}
    String encryptStore(String plain)throws Exception{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,storageKey());JSONObject envelope=new JSONObject();envelope.put("iv",android.util.Base64.encodeToString(cipher.getIV(),android.util.Base64.NO_WRAP));envelope.put("data",android.util.Base64.encodeToString(cipher.doFinal(plain.getBytes(StandardCharsets.UTF_8)),android.util.Base64.NO_WRAP));return envelope.toString();}
    String decryptStore(String encrypted)throws Exception{JSONObject envelope=new JSONObject(encrypted);byte[] iv=android.util.Base64.decode(envelope.getString("iv"),android.util.Base64.NO_WRAP);byte[] data=android.util.Base64.decode(envelope.getString("data"),android.util.Base64.NO_WRAP);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,storageKey(),new GCMParameterSpec(128,iv));return new String(cipher.doFinal(data),StandardCharsets.UTF_8);}
    boolean noteIsBlank(Note item){return item==null||((item.title==null||item.title.trim().isEmpty())&&noteContent(item).trim().isEmpty());}
