    void saveEncryptedStore(String snapshot){try{String encrypted=encryptStore(snapshot);getSharedPreferences("suiyi",0).edit().putString("secureData",encrypted).remove("notes").remove("trash").remove("labels").remove("pinnedLabels").remove("timeline").apply();RecentNotesWidgetProvider.refresh(this);}catch(Exception e){runOnUiThread(()->{storageError=true;toast("本地加密保存失败，数据未写入");});}}
    void parseStore(JSONObject data)throws Exception{JSONArray books=data.optJSONArray("notebooks");if(books!=null)for(int i=0;i<books.length();i++)notebooks.add(new Notebook(books.getJSONObject(i)));JSONArray a=data.optJSONArray("notes");if(a!=null)for(int i=0;i<a.length();i++)notes.add(new Note(a.getJSONObject(i)));JSONArray t=data.optJSONArray("trash");if(t!=null)for(int i=0;i<t.length();i++)trash.add(new Note(t.getJSONObject(i)));JSONArray l=data.optJSONArray("labels");if(l!=null){labels.clear();for(int i=0;i<l.length();i++)labels.add(l.getString(i));}JSONArray pl=data.optJSONArray("pinnedLabels");if(pl!=null)for(int i=0;i<pl.length();i++)pinnedLabels.add(pl.getString(i));JSONArray time=data.optJSONArray("timeline");if(time!=null)for(int i=0;i<time.length();i++)timeline.add(new TimeEntry(time.getJSONObject(i)));normalizeLabelHierarchy();}
    void load(){SharedPreferences prefs=getSharedPreferences("suiyi",0);String encrypted=prefs.getString("secureData",null);try{if(encrypted!=null){parseStore(new JSONObject(decryptStore(encrypted)));return;}boolean legacy=prefs.contains("notes")||prefs.contains("trash")||prefs.contains("labels")||prefs.contains("timeline");if(!legacy)return;JSONObject data=new JSONObject();data.put("notes",new JSONArray(prefs.getString("notes","[]")));data.put("trash",new JSONArray(prefs.getString("trash","[]")));data.put("labels",new JSONArray(prefs.getString("labels","[]")));data.put("pinnedLabels",new JSONArray(prefs.getString("pinnedLabels","[]")));data.put("timeline",new JSONArray(prefs.getString("timeline","[]")));parseStore(data);persist();}catch(Exception e){notes.clear();trash.clear();timeline.clear();storageError=true;}}
